constexpr lv_coord_t kSatelliteWidth = 320;
constexpr lv_coord_t kSatelliteHeight = 204;
static bool map_using_imagery = false;
static bool map_imagery_edge = false;
#if !defined(LILYSHARK_DEVICE)
static std::array<std::uint16_t, kSatelliteWidth * kSatelliteHeight> satellite_store{};
static std::array<std::uint16_t, kSatelliteWidth * kSatelliteHeight> satellite_scratch{};
static bool satellite_ready = false;
static char satellite_cache_key[48]{};
std::uint16_t *satellite_pixel_ptr() noexcept { return satellite_store.data(); }
std::uint16_t *satellite_scratch_ptr() noexcept { return satellite_scratch.data(); }
#elif defined(ESP_PLATFORM)
static std::uint16_t *satellite_store = nullptr;
static std::uint16_t *satellite_scratch = nullptr;
static bool satellite_ready = false;
static char satellite_cache_key[48]{};
std::uint16_t *satellite_pixel_ptr() noexcept
{
    if (satellite_store == nullptr) {
        satellite_store = static_cast<std::uint16_t *>(heap_caps_malloc(
            static_cast<std::size_t>(kSatelliteWidth * kSatelliteHeight) * sizeof(std::uint16_t),
            MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
        if (satellite_store == nullptr) {
            satellite_store = static_cast<std::uint16_t *>(heap_caps_malloc(
                static_cast<std::size_t>(kSatelliteWidth * kSatelliteHeight) *
                    sizeof(std::uint16_t),
                MALLOC_CAP_8BIT));
        }
    }
    return satellite_store;
}
std::uint16_t *satellite_scratch_ptr() noexcept
{
    if (satellite_scratch == nullptr) {
        satellite_scratch = static_cast<std::uint16_t *>(heap_caps_malloc(
            static_cast<std::size_t>(kSatelliteWidth * kSatelliteHeight) * sizeof(std::uint16_t),
            MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
    }
    return satellite_scratch;
}
#endif

constexpr lv_coord_t kPlotMaxW = 312;
constexpr lv_coord_t kPlotMaxH = 52;
#if !defined(LILYSHARK_DEVICE)
static std::array<std::uint16_t, kPlotMaxW * kPlotMaxH> plot_store_a{};
static std::array<std::uint16_t, kPlotMaxW * kPlotMaxH> plot_store_b{};
std::uint16_t *plot_pixels(int slot) noexcept
{
    return slot == 0 ? plot_store_a.data() : plot_store_b.data();
}
#elif defined(ESP_PLATFORM)
static std::uint16_t *plot_store_a = nullptr;
static std::uint16_t *plot_store_b = nullptr;
std::uint16_t *plot_pixels(int slot) noexcept
{
    std::uint16_t *&slot_ptr = slot == 0 ? plot_store_a : plot_store_b;
    if (slot_ptr == nullptr) {
        slot_ptr = static_cast<std::uint16_t *>(heap_caps_malloc(
            static_cast<std::size_t>(kPlotMaxW * kPlotMaxH) * sizeof(std::uint16_t),
            MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
    }
    return slot_ptr;
}
#else
std::uint16_t *plot_pixels(int) noexcept { return nullptr; }
#endif

