// A tap on a map mark opens a card over the map instead of replacing the
// screen: the operator keeps their bearings, and the two things they actually
// want next — the node's numbers, or a message to it — are one tap away.
struct MapPopup {
    bool open = false;
    int node_index = -1;
    std::uint32_t id = 0;
    char name[16]{};
    double range_m = 0.0;
    double bearing_deg = 0.0;
    double lat = 0.0;
    double lon = 0.0;
    bool has_position = false;
};
MapPopup map_popup{};

