std::uint32_t chat_active_dest() noexcept
{
    if (chat_peer_count == 0U) return 0xffffffffU;
    if (chat_peer_index >= chat_peer_count) chat_peer_index = 0;
    return chat_peers[chat_peer_index].node;
}

void chat_remember_peer(std::uint32_t node, const char *name) noexcept
{
    if (node == 0U || node == 0xffffffffU || node == localMeshtasticNodeNum()) {
        return;
    }
    for (std::size_t index = 0; index < chat_peer_count; ++index) {
        if (chat_peers[index].node != node) continue;
        if (name != nullptr && name[0] != '\0') {
            std::snprintf(chat_peers[index].name, sizeof(chat_peers[index].name), "%.7s",
                          name);
        }
        return;
    }
    if (chat_peer_count >= kChatPeerCapacity) {
        for (std::size_t index = 1; index + 1U < chat_peer_count; ++index) {
            chat_peers[index] = chat_peers[index + 1U];
        }
        chat_peer_count = kChatPeerCapacity - 1U;
        if (chat_peer_index >= chat_peer_count) chat_peer_index = 0;
    }
    ChatPeer &peer = chat_peers[chat_peer_count++];
    peer.node = node;
    if (name != nullptr && name[0] != '\0') {
        std::snprintf(peer.name, sizeof(peer.name), "%.7s", name);
    } else {
        std::snprintf(peer.name, sizeof(peer.name), "%04X",
                      static_cast<unsigned>(node & 0xffffU));
    }
}

void open_chat_with_node(std::uint32_t id, const char *name) noexcept
{
    chat_remember_peer(id, name);
    for (std::size_t index = 0; index < chat_peer_count; ++index) {
        if (chat_peers[index].node != id) continue;
        chat_peer_index = index;
        break;
    }
    open_field_tab(FieldTab::Chat);
}

bool activate_node_detail_action(bool open_chat) noexcept;

std::size_t chat_tab_first() noexcept
{
    if (chat_peer_count <= kChatTabVisible) return 0U;
    if (chat_peer_index + 1U <= kChatTabVisible) return 0U;
    return chat_peer_index + 1U - kChatTabVisible;
}

std::size_t chat_tab_shown() noexcept
{
    if (chat_peer_count == 0U) return 1U;
    return chat_peer_count < kChatTabVisible ? chat_peer_count : kChatTabVisible;
}

void chat_cycle_dest(int step) noexcept
{
    if (chat_peer_count == 0U) return;
    const std::size_t count = chat_peer_count;
    chat_peer_index = static_cast<std::size_t>(
        (static_cast<int>(chat_peer_index) + step + static_cast<int>(count)) %
        static_cast<int>(count));
    chat_scroll_offset = 0;
}

void chat_sync_unread() noexcept
{
    std::uint16_t total = 0;
    for (std::size_t index = 0; index < chat_peer_count; ++index) {
        total = static_cast<std::uint16_t>(total + chat_peers[index].unread);
    }
    chat_unread = total > 99U ? 99U : static_cast<std::uint8_t>(total);
}

void chat_clear_peer_unread(std::uint32_t peer) noexcept
{
    for (std::size_t index = 0; index < chat_peer_count; ++index) {
        if (chat_peers[index].node != peer) continue;
        chat_peers[index].unread = 0;
        break;
    }
    chat_sync_unread();
}

struct ChatArchiveHeader {
    std::uint32_t magic;
    std::uint16_t version;
    std::uint16_t count;
    std::uint16_t start;
    std::uint16_t reserved;
};
constexpr std::uint32_t kChatArchiveMagic = 0x4C534348UL;  // "LSCH"
constexpr std::uint16_t kChatArchiveVersion = 1U;
constexpr std::size_t kChatArchiveSize = sizeof(ChatArchiveHeader) + sizeof(chat_log);

/// The log as bytes. Kept apart from the NVS call so the round trip can be
/// exercised on the host, where there is no NVS to exercise it against.
std::size_t encode_chat_archive(std::uint8_t *bytes, std::size_t capacity) noexcept
{
    if(bytes == nullptr || capacity < kChatArchiveSize) return 0;
    ChatArchiveHeader header{};
    header.magic = kChatArchiveMagic;
    header.version = kChatArchiveVersion;
    header.count = static_cast<std::uint16_t>(chat_log_count);
    header.start = static_cast<std::uint16_t>(chat_log_start);
    header.reserved = 0U;
    std::memcpy(bytes, &header, sizeof(header));
    std::memcpy(bytes + sizeof(header), chat_log, sizeof(chat_log));
    return kChatArchiveSize;
}

bool decode_chat_archive(const std::uint8_t *bytes, std::size_t size) noexcept
{
    if(bytes == nullptr || size != kChatArchiveSize) return false;
    ChatArchiveHeader header{};
    std::memcpy(&header, bytes, sizeof(header));
    if(header.magic != kChatArchiveMagic || header.version != kChatArchiveVersion) return false;
    if(header.count > kChatLogCapacity || header.start >= kChatLogCapacity) return false;
    std::memcpy(chat_log, bytes + sizeof(header), sizeof(chat_log));
    chat_log_count = header.count;
    chat_log_start = header.start;
    return true;
}

void chat_push(const char *from, const char *text, bool mine,
               std::uint32_t peer = 0xffffffffU, const char *when = nullptr) noexcept
{
    if (from == nullptr || text == nullptr || text[0] == '\0') return;
    const std::size_t slot = (chat_log_start + chat_log_count) % kChatLogCapacity;
    ChatLine &line = chat_log[slot];
    std::snprintf(line.from, sizeof(line.from), "%.7s", from);
    std::snprintf(line.text, sizeof(line.text), "%s", text);
    if (when != nullptr && when[0] != '\0') {
        std::snprintf(line.when, sizeof(line.when), "%.5s", when);
    } else {
        line.when[0] = '\0';
    }
    line.peer = peer;
    line.mine = mine;
    if (chat_log_count < kChatLogCapacity) {
        ++chat_log_count;
    } else {
        chat_log_start = (chat_log_start + 1U) % kChatLogCapacity;
    }
#if defined(LILYSHARK_DEVICE)
    chat_log_dirty = true;
    chat_log_save_due_ms = millis() + kChatSaveDebounceMs;
#endif
    if (!mine && peer != 0U && peer != 0xffffffffU) {
        chat_remember_peer(peer, from);
    }
    if (!mine && !(chat_open && chat_active_dest() == peer)) {
        for (std::size_t index = 0; index < chat_peer_count; ++index) {
            if (chat_peers[index].node != peer) continue;
            if (chat_peers[index].unread < 99U) ++chat_peers[index].unread;
            break;
        }
    }
    chat_sync_unread();
#if defined(LILYSHARK_DEVICE)
    if (chat_open) live_data_dirty = true;
#endif
}

