lv_obj_t * add_scaled_wordmark(lv_obj_t * parent, lv_coord_t left, lv_coord_t top,
                               lv_coord_t visual_width)
{
    const std::uint32_t scale = static_cast<std::uint32_t>(visual_width) * LV_SCALE_NONE /
                                LILYSHARK_WORDMARK_A8_WIDTH;
    const lv_coord_t visual_height = static_cast<lv_coord_t>(
        (LILYSHARK_WORDMARK_A8_HEIGHT * scale) / LV_SCALE_NONE);
    const lv_coord_t object_x = left -
        (static_cast<lv_coord_t>(LILYSHARK_WORDMARK_A8_WIDTH) - visual_width) / 2;
    const lv_coord_t object_y = top -
        (static_cast<lv_coord_t>(LILYSHARK_WORDMARK_A8_HEIGHT) - visual_height) / 2;
    return add_wordmark(parent, object_x, object_y, scale);
}

void draw_pixel_line(lv_obj_t * parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                     lv_coord_t height, uint8_t seed, lv_color_t color, bool bars = false)
{
    if(width < 2 || height < 2) return;

    if(trace_buffer_index >= trace_buffers.size()) return;
    auto & points = trace_buffers[trace_buffer_index++];
    const lv_coord_t step = width > 150 ? 2 : 3;
    size_t point_count = 0;
    for(lv_coord_t px = 0; px < width && point_count < points.size(); px += step) {
        const uint32_t hash = static_cast<uint32_t>((px + seed * 17) * 1103515245u + seed * 12345u);
        const lv_coord_t jitter = static_cast<lv_coord_t>((hash >> 27) % static_cast<uint32_t>(height - 2));
        points[point_count++] = {px, static_cast<lv_coord_t>(1 + jitter)};
    }

    lv_obj_t * line = lv_line_create(parent);
    theme::reset(line);
    lv_line_set_points(line, points.data(), static_cast<uint32_t>(point_count));
    lv_obj_set_pos(line, x, y);
    lv_obj_set_size(line, width, height);
    lv_obj_set_style_line_color(line, color, 0);
    lv_obj_set_style_line_width(line, bars ? 1 : 1, 0);
    lv_obj_set_style_line_rounded(line, false, 0);

    if(bars) {
        for(size_t index = 0; index < point_count; index += 4) {
            const lv_coord_t bar_x = x + static_cast<lv_coord_t>(points[index].x);
            const lv_coord_t bar_y = y + static_cast<lv_coord_t>(points[index].y);
            theme::rect(parent, bar_x, bar_y, 1, y + height - bar_y, color);
        }
    }
}

void add_grid(lv_obj_t * parent, lv_coord_t x, lv_coord_t y, lv_coord_t width, lv_coord_t height,
              lv_coord_t x_step, lv_coord_t y_step)
{
    for(lv_coord_t px = x; px <= x + width; px += x_step) theme::rule_line(parent, px, y, 1, height, theme::grid());
    for(lv_coord_t py = y; py <= y + height; py += y_step) theme::rule_line(parent, x, py, width, 1, theme::grid());
}

int plot_scale(int value, int low, int high, int height) noexcept
{
    if (high <= low || height <= 1) return 0;
    int bar = ((value - low) * (height - 1)) / (high - low);
    if (bar < 0) bar = 0;
    if (bar > height - 1) bar = height - 1;
    return bar;
}

int plot_sample_at(const int *values, std::size_t count, int column, int columns) noexcept
{
    if (values == nullptr || count == 0U || columns <= 0) return 0;
    if (count == 1U) return values[0];
    if (columns == 1) return values[count - 1U];
    const int span = static_cast<int>(count - 1U);
    const int num = column * span;
    const int den = columns - 1;
    const int i0 = num / den;
    const int i1 = i0 + 1 < static_cast<int>(count) ? i0 + 1 : i0;
    const int frac = num - i0 * den;
    return (values[i0] * (den - frac) + values[i1] * frac) / den;
}

void draw_plot_columns(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                       lv_coord_t height, const int *values, std::size_t count,
                       int low, int high, lv_color_t fill, lv_color_t tip) noexcept
{
    if (count == 0U || width < 2 || height < 4) return;
    int columns = width;
    int col_w = 1;
    if (columns > 96) {
        col_w = 2;
        columns = width / 2;
    }
    if (columns > 120) columns = 120;
    int prev_top = -1;
    for (int column = 0; column < columns; ++column) {
        const int value = plot_sample_at(values, count, column, columns);
        const int bar = plot_scale(value, low, high, height);
        const lv_coord_t px = x + static_cast<lv_coord_t>((column * width) / columns);
        const lv_coord_t top = y + height - static_cast<lv_coord_t>(bar);
        if (prev_top >= 0) {
            const lv_coord_t lo = prev_top < top ? prev_top : top;
            const lv_coord_t hi = prev_top > top ? prev_top : top;
            theme::rect(parent, px, lo, static_cast<lv_coord_t>(col_w),
                        hi - lo + 1, fill);
        }
        theme::rect(parent, px, top, static_cast<lv_coord_t>(col_w), 2, tip);
        prev_top = top;
    }
}

void draw_field_plot(lv_obj_t *parent, int slot, lv_coord_t x, lv_coord_t y,
                     lv_coord_t width, lv_coord_t height, const int *values,
                     std::size_t count, int low, int high, lv_color_t fill,
                     lv_color_t tip, bool mark_zero) noexcept
{
    if (width < 8 || height < 8 || width > kPlotMaxW || height > kPlotMaxH) return;
    std::uint16_t *pixels = plot_pixels(slot);
    if (pixels == nullptr) {
        theme::rect(parent, x, y, width, height, lv_color_hex(0x040C0B));
        for (lv_coord_t gy = y + 8; gy < y + height; gy += 8) {
            theme::rect(parent, x, gy, width, 1, lv_color_hex(0x142826));
        }
        draw_plot_columns(parent, x, y, width, height, values, count, low, high, fill, tip);
        return;
    }
    const std::uint16_t bg = lv_color_to_u16(lv_color_hex(0x040C0B));
    const std::uint16_t grid = lv_color_to_u16(lv_color_hex(0x142826));
    const std::uint16_t axis = lv_color_to_u16(lv_color_hex(0x2A4A46));
    const std::uint16_t body = lv_color_to_u16(fill);
    const std::uint16_t cap = lv_color_to_u16(tip);
    const std::uint16_t stem = lv_color_to_u16(lv_color_mix(fill, lv_color_hex(0x040C0B), 160));
    const int stride = width;
    for (int row = 0; row < height; ++row) {
        std::uint16_t *line = pixels + row * stride;
        const std::uint16_t row_color = (row % 8 == 0) ? grid : bg;
        for (int col = 0; col < width; ++col) line[col] = row_color;
    }
    if (mark_zero && low < 0 && high > 0) {
        const int zero_y = height - 1 - plot_scale(0, low, high, height);
        if (zero_y >= 0 && zero_y < height) {
            std::uint16_t *line = pixels + zero_y * stride;
            for (int col = 0; col < width; ++col) line[col] = axis;
        }
    }
    if (count > 0U) {
        int prev_y = -1;
        for (int col = 0; col < width; ++col) {
            const int value = plot_sample_at(values, count, col, width);
            const int bar = plot_scale(value, low, high, height);
            const int y0 = height - 1 - bar;
            if (prev_y >= 0) {
                const int lo = prev_y < y0 ? prev_y : y0;
                const int hi = prev_y > y0 ? prev_y : y0;
                for (int row = lo; row <= hi && row < height; ++row) {
                    pixels[row * stride + col] = body;
                }
            }
            for (int row = y0; row <= y0 + 3 && row < height; ++row) {
                pixels[row * stride + col] = stem;
            }
            if (y0 >= 0 && y0 < height) pixels[y0 * stride + col] = cap;
            if (y0 > 0) pixels[(y0 - 1) * stride + col] = cap;
            prev_y = y0;
        }
    }
    lv_obj_t *canvas = lv_canvas_create(parent);
    theme::reset(canvas);
    lv_canvas_set_buffer(canvas, pixels, width, height, LV_COLOR_FORMAT_RGB565);
    lv_obj_set_pos(canvas, x, y);
}

void draw_linear_gauge(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, lv_coord_t width,
                       lv_coord_t height, int value, int low, int high,
                       lv_color_t fill) noexcept
{
    theme::rect(parent, x, y, width, height, lv_color_hex(0x040C0B));
    draw_outline_rect(parent, x, y, width, height, theme::grid());
    const int fill_w = plot_scale(value, low, high, width);
    if (fill_w > 1) {
        theme::rect(parent, x + 1, y + 2, static_cast<lv_coord_t>(fill_w - 1),
                    height - 4, fill);
        theme::rect(parent, x + static_cast<lv_coord_t>(fill_w) - 1, y + 1, 2,
                    height - 2, theme::text());
    }
    for (int tick = 1; tick < 10; ++tick) {
        const lv_coord_t tx = x + static_cast<lv_coord_t>((tick * (width - 1)) / 10);
        theme::rect(parent, tx, y + height - 4, 1, 3, theme::rule());
    }
}

void draw_map_ring(lv_obj_t *parent, lv_coord_t cx, lv_coord_t cy, lv_coord_t radius,
                   lv_color_t color, lv_coord_t width = 1) noexcept
{
    if (radius < 3 || trace_buffer_index >= trace_buffers.size()) return;
    auto &points = trace_buffers[trace_buffer_index++];
    constexpr std::size_t kSeg = 36;
    for (std::size_t index = 0; index <= kSeg; ++index) {
        const double angle = (6.283185307179586 * static_cast<double>(index)) /
                             static_cast<double>(kSeg);
        points[index].x = static_cast<float>(cx) +
            static_cast<float>(radius) * static_cast<float>(std::cos(angle));
        points[index].y = static_cast<float>(cy) +
            static_cast<float>(radius) * static_cast<float>(std::sin(angle));
    }
    lv_obj_t *line = lv_line_create(parent);
    theme::reset(line);
    lv_line_set_points(line, points.data(), static_cast<std::uint32_t>(kSeg + 1U));
    lv_obj_set_pos(line, 0, 0);
    lv_obj_set_style_line_color(line, color, 0);
    lv_obj_set_style_line_width(line, width < 1 ? 1 : width, 0);
}

void draw_map_segment(lv_obj_t *parent, lv_coord_t x0, lv_coord_t y0, lv_coord_t x1,
                      lv_coord_t y1, lv_color_t color) noexcept
{
    if (trace_buffer_index >= trace_buffers.size()) return;
    auto &points = trace_buffers[trace_buffer_index++];
    points[0].x = static_cast<float>(x0);
    points[0].y = static_cast<float>(y0);
    points[1].x = static_cast<float>(x1);
    points[1].y = static_cast<float>(y1);
    lv_obj_t *line = lv_line_create(parent);
    theme::reset(line);
    lv_line_set_points(line, points.data(), 2U);
    lv_obj_set_pos(line, 0, 0);
    lv_obj_set_style_line_color(line, color, 0);
    lv_obj_set_style_line_width(line, 1, 0);
}

void draw_map_chevron(lv_obj_t *parent, lv_coord_t x, lv_coord_t y, double east_m,
                      double north_m) noexcept
{
    const double len = std::hypot(east_m, north_m);
    if (len < 1.0) return;
    const double ux = east_m / len;
    const double uy = -north_m / len;
    const lv_coord_t ax = static_cast<lv_coord_t>(std::lround(static_cast<double>(x) - ux * 7.0 + uy * 4.0));
    const lv_coord_t ay = static_cast<lv_coord_t>(std::lround(static_cast<double>(y) - uy * 7.0 - ux * 4.0));
    const lv_coord_t bx = static_cast<lv_coord_t>(std::lround(static_cast<double>(x) - ux * 7.0 - uy * 4.0));
    const lv_coord_t by = static_cast<lv_coord_t>(std::lround(static_cast<double>(y) - uy * 7.0 + ux * 4.0));
    draw_map_segment(parent, ax, ay, x, y, theme::pink());
    draw_map_segment(parent, bx, by, x, y, theme::pink());
}

/// A raw 1 Hz fix wanders by metres even when standing still, and at a zoom
/// where the screen is forty metres across that wander is the whole picture.
/// This averages the recent fixes so the marker sits still, and snaps to the
/// new position when the jump is too large to be noise — that is walking, not
/// jitter.
void map_smooth_position(double raw_lat, double raw_lon, double &out_lat,
                         double &out_lon) noexcept
{
    static double smooth_lat = 0.0;
    static double smooth_lon = 0.0;
    static bool have_smooth = false;

    if (!have_smooth) {
        smooth_lat = raw_lat;
        smooth_lon = raw_lon;
        have_smooth = true;
    } else {
        const double lat_rad = smooth_lat * 0.017453292519943295;
        const double de = (raw_lon - smooth_lon) * 111320.0 * std::cos(lat_rad);
        const double dn = (raw_lat - smooth_lat) * 110540.0;
        if (std::hypot(de, dn) > 15.0) {
            smooth_lat = raw_lat;
            smooth_lon = raw_lon;
        } else {
            constexpr double kBlend = 0.25;
            smooth_lat += (raw_lat - smooth_lat) * kBlend;
            smooth_lon += (raw_lon - smooth_lon) * kBlend;
        }
    }
    out_lat = smooth_lat;
    out_lon = smooth_lon;
}

double map_fix_accuracy_m(float hdop, std::uint8_t satellites) noexcept
{
    double meters = 0.0;
    if (hdop > 0.05f) {
        meters = static_cast<double>(hdop) * 5.0;
    } else if (satellites > 0U) {
        const int extra = satellites > 4U ? static_cast<int>(satellites) - 4 : 0;
        meters = 25.0 - static_cast<double>(extra) * 2.0;
        if (meters < 8.0) meters = 8.0;
    } else {
        return 0.0;
    }
    if (meters < 5.0) meters = 5.0;
    if (meters > 120.0) meters = 120.0;
    return meters;
}

void format_map_range(char *output, std::size_t capacity, double meters) noexcept
{
    if (output == nullptr || capacity == 0U) return;
    if (meters < 1.0) {
        std::snprintf(output, capacity, "<1M");
    } else if (meters >= 10000.0) {
        std::snprintf(output, capacity, "%.0fKM", meters / 1000.0);
    } else if (meters >= 1000.0) {
        std::snprintf(output, capacity, "%.1fKM", meters / 1000.0);
    } else {
        std::snprintf(output, capacity, "%.0fM", meters);
    }
}

void format_hemisphere_fix(char *output, std::size_t capacity, double lat,
                           double lon) noexcept
{
    if (output == nullptr || capacity == 0U) return;
    std::snprintf(output, capacity, "%.4f %c  %.3f %c",
                  std::abs(lat), lat >= 0.0 ? 'N' : 'S',
                  std::abs(lon), lon >= 0.0 ? 'E' : 'W');
}

double map_bearing_deg(double east_m, double north_m) noexcept
{
    double deg = std::atan2(east_m, north_m) * (180.0 / 3.141592653589793);
    if (deg < 0.0) deg += 360.0;
    return deg;
}

void field_local_meters(double from_lat, double from_lon, double to_lat, double to_lon,
                        double &east_m, double &north_m) noexcept
{
    const double lat_rad = from_lat * 0.017453292519943295;
    east_m = (to_lon - from_lon) * 111320.0 * std::cos(lat_rad);
    north_m = (to_lat - from_lat) * 110540.0;
}

bool field_peer_fix(std::size_t raw_index, double &lat, double &lon) noexcept
{
    if (raw_index >= kFieldPeers.size()) return false;
    lat = kFieldPeers[raw_index].lat;
    lon = kFieldPeers[raw_index].lon;
    return true;
}

#if !defined(LILYSHARK_DEVICE)
void simulator_you_latlon(double &lat, double &lon) noexcept
{
    constexpr double origin_lat = 37.77490;
    constexpr double origin_lon = -122.41940;
    const std::uint32_t phase =
        static_cast<std::uint32_t>(simulator_live_telemetry.tick() / 4U);
    const double walk = static_cast<double>(phase) * 0.18;
    const double lat_rad = origin_lat * 0.017453292519943295;
    const double you_east = 70.0 * std::cos(walk);
    const double you_north = 70.0 * std::sin(walk);
    lat = origin_lat + you_north / 110540.0;
    lon = origin_lon + you_east / (111320.0 * std::cos(lat_rad));
}

bool simulator_node_fix(const simulator::NodeSnapshot &node, double &lat,
                        double &lon) noexcept
{
    const auto &snapshot = simulator_live_telemetry.nodes();
    for (std::size_t index = 0; index < snapshot.nodes.size(); ++index) {
        if (snapshot.nodes[index].id != node.id) continue;
        return field_peer_fix(index, lat, lon);
    }
    return false;
}
#endif

void draw_node_fix_strip(lv_obj_t *parent, double lat, double lon, bool have_you,
                         double you_lat, double you_lon) noexcept
{
    char line[40]{};
    format_hemisphere_fix(line, sizeof(line), lat, lon);
    put_label(parent, line, 136, 64, theme::pink(), &font_pixel_6x8);
    if (!have_you) return;
    double east_m = 0.0;
    double north_m = 0.0;
    field_local_meters(you_lat, you_lon, lat, lon, east_m, north_m);
    char range[12]{};
    format_map_range(range, sizeof(range), std::hypot(east_m, north_m));
    std::snprintf(line, sizeof(line), "%s  %03.0f", range, map_bearing_deg(east_m, north_m));
    put_label(parent, line, 136, 74, theme::pink(), &font_pixel_6x8);
}

struct MapMark {
    const char *name = "";
    double east_m = 0.0;
    double north_m = 0.0;
    bool you = false;
    bool selected = false;
    int node_index = -1;
};

double map_meters_per_pixel_at(double latitude_degrees, int zoom) noexcept
{
    return 156543.03392804097 * std::cos(latitude_degrees * 0.017453292519943295) /
           static_cast<double>(1 << zoom);
}

double map_meters_per_pixel(double latitude_degrees) noexcept
{
    return map_meters_per_pixel_at(latitude_degrees, map_zoom);
}

std::uint32_t map_hash2(int x, int y) noexcept
{
    std::uint32_t h = static_cast<std::uint32_t>(x) * 374761393U +
                      static_cast<std::uint32_t>(y) * 668265263U + 0x9e3779b9U;
    h = (h ^ (h >> 13U)) * 1274126177U;
    return h ^ (h >> 16U);
}

float map_value_noise(double world_x, double world_y, double cell) noexcept
{
    const double gx = world_x / cell;
    const double gy = world_y / cell;
    const int x0 = static_cast<int>(std::floor(gx));
    const int y0 = static_cast<int>(std::floor(gy));
    const float fx = static_cast<float>(gx - static_cast<double>(x0));
    const float fy = static_cast<float>(gy - static_cast<double>(y0));
    const float ux = fx * fx * (3.0f - 2.0f * fx);
    const float uy = fy * fy * (3.0f - 2.0f * fy);
    const auto sample = [](int x, int y) {
        return static_cast<float>(map_hash2(x, y) & 1023U) / 1023.0f;
    };
    const float a = sample(x0, y0);
    const float b = sample(x0 + 1, y0);
    const float c = sample(x0, y0 + 1);
    const float d = sample(x0 + 1, y0 + 1);
    return (a + (b - a) * ux) * (1.0f - uy) + (c + (d - c) * ux) * uy;
}

double map_grid_distance(double value, double step) noexcept
{
    const double nearest = std::round(value / step) * step;
    return std::abs(value - nearest);
}

void paint_field_pixels(std::uint16_t *pixels, double origin_lat, double origin_lon,
                        double meters_per_pixel) noexcept
{
    if (pixels == nullptr || meters_per_pixel < 0.05) return;
    const double lat_rad = origin_lat * 0.017453292519943295;
    const double origin_east = origin_lon * 111320.0 * std::cos(lat_rad);
    const double origin_north = origin_lat * 110540.0;
    const lv_coord_t cx = kSatelliteWidth / 2;
    const lv_coord_t cy = kSatelliteHeight / 2;
    for (lv_coord_t y = 0; y < kSatelliteHeight; ++y) {
        const double north = origin_north + (static_cast<double>(cy - y) * meters_per_pixel);
        for (lv_coord_t x = 0; x < kSatelliteWidth; ++x) {
            const double east = origin_east + (static_cast<double>(x - cx) * meters_per_pixel);
            const float hills = map_value_noise(east, north, 220.0) * 0.55f +
                                map_value_noise(east, north, 78.0) * 0.30f +
                                map_value_noise(east, north, 26.0) * 0.15f;
            const float water = map_value_noise(east + 400.0, north - 180.0, 340.0);
            const int cell_x = static_cast<int>(std::floor(east / 120.0));
            const int cell_y = static_cast<int>(std::floor(north / 120.0));
            const std::uint32_t cell = map_hash2(cell_x, cell_y);
            const bool ns_road = (cell & 3U) != 0U;
            const bool ew_road = (cell & 12U) != 0U;
            const bool park = ((cell >> 4U) % 11U) == 0U && hills > 0.34f && hills < 0.62f;
            const double road = std::min(ns_road ? map_grid_distance(east, 120.0) : 1.0e9,
                                         ew_road ? map_grid_distance(north, 120.0) : 1.0e9);
            const double alley = std::min(map_grid_distance(east, 40.0),
                                          map_grid_distance(north, 40.0));
            std::uint8_t red;
            std::uint8_t green;
            std::uint8_t blue;
            if (map_satellite && !map_chart) {
                if (water < 0.31f) {
                    red = 18; green = 42; blue = 52;
                } else if (park) {
                    red = 46; green = 78; blue = 36;
                } else if (hills < 0.40f) {
                    red = 58; green = 82; blue = 38;
                } else if (hills < 0.62f) {
                    red = 92; green = 88; blue = 48;
                } else {
                    red = 132; green = 112; blue = 72;
                }
                if (road < 7.0) {
                    red = 52; green = 50; blue = 46;
                } else if (alley < 3.5 && ((cell >> 8U) & 1U) != 0U) {
                    red = static_cast<std::uint8_t>(red * 3 / 4);
                    green = static_cast<std::uint8_t>(green * 3 / 4);
                    blue = static_cast<std::uint8_t>(blue * 3 / 4);
                }
            } else {
                if (water < 0.31f) {
                    red = 8; green = 16; blue = 30;
                } else if (park) {
                    red = 10; green = 28; blue = 20;
                } else {
                    const int band = static_cast<int>(hills * 8.0f);
                    red = static_cast<std::uint8_t>(10 + band);
                    green = static_cast<std::uint8_t>(16 + band);
                    blue = static_cast<std::uint8_t>(24 + band * 2);
                }
                if (road < 7.0) {
                    red = 78; green = 88; blue = 104;
                } else if (alley < 3.5 && ((cell >> 8U) & 1U) != 0U) {
                    red = 36; green = 44; blue = 56;
                }
                const int contour = static_cast<int>(hills * 18.0f);
                if (std::abs((hills * 18.0f) - static_cast<float>(contour)) < 0.08f &&
                    road >= 7.0) {
                    red = 28; green = 52; blue = 62;
                }
            }
            pixels[static_cast<std::size_t>(y) * kSatelliteWidth + static_cast<std::size_t>(x)] =
                lv_color_to_u16(lv_color_make(red, green, blue));
        }
    }
}

#if !defined(LILYSHARK_DEVICE) || defined(ESP_PLATFORM)
bool load_map_pixels_from_file(const char *path, std::uint16_t *dest) noexcept
{
    if (path == nullptr || path[0] == '\0' || dest == nullptr) return false;
#if defined(ESP_PLATFORM)
    if (!sd_mounted) return false;
    fs::File file = SD.open(path);
    if (!file) return false;
    const std::size_t want =
        static_cast<std::size_t>(kSatelliteWidth * kSatelliteHeight) * sizeof(std::uint16_t);
    const std::size_t got = file.read(reinterpret_cast<std::uint8_t *>(dest), want);
    file.close();
    return got == want;
#else
    FILE *file = std::fopen(path, "rb");
    if (file == nullptr) return false;
    const std::size_t want =
        static_cast<std::size_t>(kSatelliteWidth * kSatelliteHeight) * sizeof(std::uint16_t);
    const std::size_t got = std::fread(dest, 1, want, file);
    std::fclose(file);
    return got == want;
#endif
}

double map_cell_coord(double degrees) noexcept
{
    return std::round(degrees * 1000.0) / 1000.0;
}

void blit_map_tile(const std::uint16_t *src, std::uint16_t *dest, int offset_x,
                   int offset_y) noexcept
{
    if (src == nullptr || dest == nullptr) return;
    for (lv_coord_t y = 0; y < kSatelliteHeight; ++y) {
        const int dy = static_cast<int>(y) + offset_y;
        if (dy < 0 || dy >= kSatelliteHeight) continue;
        for (lv_coord_t x = 0; x < kSatelliteWidth; ++x) {
            const int dx = static_cast<int>(x) + offset_x;
            if (dx < 0 || dx >= kSatelliteWidth) continue;
            dest[static_cast<std::size_t>(dy) * kSatelliteWidth + static_cast<std::size_t>(dx)] =
                src[static_cast<std::size_t>(y) * kSatelliteWidth + static_cast<std::size_t>(x)];
        }
    }
}

// A microSD tile pyramid, so the map works away from the baked location.
//
// Tiles baked into flash cover one spot. Drive out of it and the imagery is
// gone, and putting it back means a rebuild and a reflash. Card tiles are laid
// out on the Web Mercator pixel grid instead: tile (i, j) at zoom z is exactly
// the world pixels [i*320, i*320+320) by [j*204, j*204+204), so they tile the
// plane with no gaps and no overlap. The 0.001-degree cell scheme cannot do
// that -- a cell is 55 m by 87 m while a z20 tile spans only 37 m, so at deep
// zoom neighbouring cells fall short of each other and leave holes.
constexpr double kMapBasePx = 256.0;

double map_world_span_px(int zoom) noexcept
{
    return kMapBasePx * static_cast<double>(1UL << static_cast<unsigned>(zoom));
}

double map_world_px_x(double longitude_degrees, int zoom) noexcept
{
    return (longitude_degrees + 180.0) / 360.0 * map_world_span_px(zoom);
}

double map_world_px_y(double latitude_degrees, int zoom) noexcept
{
    const double sine = std::sin(latitude_degrees * 0.017453292519943295);
    const double clamped = sine > 0.9999 ? 0.9999 : (sine < -0.9999 ? -0.9999 : sine);
    return (0.5 - std::log((1.0 + clamped) / (1.0 - clamped)) /
                     (4.0 * 3.14159265358979323846)) *
           map_world_span_px(zoom);
}

// Where the card is mounted on device. On the host the same layout lives in
// the working tree, so the arithmetic can be exercised without a card.
#if defined(ESP_PLATFORM)
constexpr const char *kMapCardRoot = "/maps";
#else
constexpr const char *kMapCardRoot = "assets/maps/card";
#endif

double map_lon_at_world_px(double px, int zoom) noexcept
{
    return px / map_world_span_px(zoom) * 360.0 - 180.0;
}

double map_lat_at_world_px(double py, int zoom) noexcept
{
    const double n = 3.14159265358979323846 * (1.0 - 2.0 * py / map_world_span_px(zoom));
    return std::atan(std::sinh(n)) * 57.29577951308232;
}

/// Which card tiles cover this view, and where the first one lands. Split out
/// from the blit so the arithmetic is testable with no card present -- getting
/// an offset sign wrong here is exactly what put the imagery off screen before.
struct MapCardPlacement {
    long first_x = 0;
    long last_x = 0;
    long first_y = 0;
    long last_y = 0;
    int offset_x = 0;
    int offset_y = 0;
};

MapCardPlacement map_card_placement(double latitude_degrees, double longitude_degrees,
                                    int zoom) noexcept
{
    const double left_px = map_world_px_x(longitude_degrees, zoom) -
                           static_cast<double>(kSatelliteWidth) / 2.0;
    const double top_px = map_world_px_y(latitude_degrees, zoom) -
                          static_cast<double>(kSatelliteHeight) / 2.0;
    MapCardPlacement placement{};
    placement.first_x = static_cast<long>(std::floor(left_px / kSatelliteWidth));
    placement.last_x = static_cast<long>(
        std::floor((left_px + kSatelliteWidth - 1.0) / kSatelliteWidth));
    placement.first_y = static_cast<long>(std::floor(top_px / kSatelliteHeight));
    placement.last_y = static_cast<long>(
        std::floor((top_px + kSatelliteHeight - 1.0) / kSatelliteHeight));
    placement.offset_x = static_cast<int>(
        std::lround(static_cast<double>(placement.first_x) * kSatelliteWidth - left_px));
    placement.offset_y = static_cast<int>(
        std::lround(static_cast<double>(placement.first_y) * kSatelliteHeight - top_px));
    return placement;
}

bool load_map_grid_tile(int zoom, long tile_x, long tile_y, std::uint16_t *dest) noexcept
{
    const char *kind = map_satellite ? "sat" : "dark";
    char path[128]{};
    std::snprintf(path, sizeof(path), "%s/%s/z%d/%ld_%ld.rgb565", kMapCardRoot, kind,
                  zoom, tile_x, tile_y);
    return load_map_pixels_from_file(path, dest);
}

/// Paint whatever the card holds for this view. True if any tile landed;
/// missing neighbours leave the chart underneath showing, which is what you
/// want at the edge of the area you prepared rather than a black band.
bool blit_map_card(std::uint16_t *pixels, std::uint16_t *scratch,
                   double latitude_degrees, double longitude_degrees, int zoom,
                   bool *fully_covered = nullptr) noexcept
{
    if (fully_covered != nullptr) *fully_covered = false;
    if (pixels == nullptr || scratch == nullptr) return false;
    const MapCardPlacement placement =
        map_card_placement(latitude_degrees, longitude_degrees, zoom);
    long wanted = 0;
    long loaded = 0;
    for (long tile_y = placement.first_y; tile_y <= placement.last_y; ++tile_y) {
        for (long tile_x = placement.first_x; tile_x <= placement.last_x; ++tile_x) {
            ++wanted;
            if (!load_map_grid_tile(zoom, tile_x, tile_y, scratch)) continue;
            ++loaded;
            const int offset_x =
                placement.offset_x +
                static_cast<int>(tile_x - placement.first_x) * kSatelliteWidth;
            const int offset_y =
                placement.offset_y +
                static_cast<int>(tile_y - placement.first_y) * kSatelliteHeight;
            blit_map_tile(scratch, pixels, offset_x, offset_y);
        }
    }
    if (fully_covered != nullptr) *fully_covered = loaded == wanted && wanted > 0;
    return loaded > 0;
}

bool try_load_map_cell(double cell_lat, double cell_lon, std::uint16_t *dest) noexcept
{
    if (dest == nullptr) return false;
    const char *kind = map_satellite ? "sat" : "dark";
#if !defined(LILYSHARK_DEVICE)
    char bundled[256]{};
    std::snprintf(bundled, sizeof(bundled),
                  "assets/maps/%s_%.3f_%.3f_z%d.rgb565",
                  kind, cell_lat, cell_lon, map_zoom);
    if (map_bundled_tiles_only) return load_map_pixels_from_file(bundled, dest);
    char cached[256]{};
    std::snprintf(cached, sizeof(cached),
                  "/tmp/lilyshark-%s-%.3f_%.3f_z%d.rgb565",
                  kind, cell_lat, cell_lon, map_zoom);
    return load_map_pixels_from_file(cached, dest) ||
           load_map_pixels_from_file(bundled, dest);
#else
    // microSD first so a card can always override or extend the imagery.
    char sd_path[96]{};
    std::snprintf(sd_path, sizeof(sd_path), "/maps/%s_%.3f_%.3f_z%d.rgb565",
                  kind, cell_lat, cell_lon, map_zoom);
    if (load_map_pixels_from_file(sd_path, dest)) return true;
    // Then the tiles baked into flash, so a device with no card still shows
    // a real map instead of an empty grid.
    const std::uint16_t *baked = ::lilyshark::bakedMapTile(kind, cell_lat, cell_lon, map_zoom);
    if (baked != nullptr) {
        std::memcpy(dest, baked,
                    static_cast<std::size_t>(kSatelliteWidth) *
                        static_cast<std::size_t>(kSatelliteHeight) * sizeof(std::uint16_t));
        return true;
    }
    // Past the deepest imagery, magnify the closest tile rather than dropping
    // to the bare grid. The picture gains no detail — the source has none —
    // but the marks keep spreading apart, which is the point of zooming in on
    // two operators standing together.
    const int deepest =
        ::lilyshark::bakedMapTileZoomAtOrBelow(kind, cell_lat, cell_lon, map_zoom);
    if (deepest > 0 && deepest < map_zoom) {
        const std::uint16_t *coarse =
            ::lilyshark::bakedMapTile(kind, cell_lat, cell_lon, deepest);
        if (coarse != nullptr) {
            const int factor = 1 << (map_zoom - deepest);
            for (lv_coord_t y = 0; y < kSatelliteHeight; ++y) {
                // Sample about the tile centre so magnifying does not drift.
                const int sy = kSatelliteHeight / 2 +
                               ((static_cast<int>(y) - kSatelliteHeight / 2) / factor);
                for (lv_coord_t x = 0; x < kSatelliteWidth; ++x) {
                    const int sx = kSatelliteWidth / 2 +
                                   ((static_cast<int>(x) - kSatelliteWidth / 2) / factor);
                    dest[static_cast<std::size_t>(y) * kSatelliteWidth +
                         static_cast<std::size_t>(x)] =
                        coarse[static_cast<std::size_t>(sy) * kSatelliteWidth +
                               static_cast<std::size_t>(sx)];
                }
            }
            return true;
        }
    }
    return false;
#endif
}

bool fetch_map_cell(double cell_lat, double cell_lon, std::uint16_t *dest) noexcept
{
#if !defined(LILYSHARK_DEVICE)
    if (map_bundled_tiles_only) return false;
    const char *skip = std::getenv("LILYSHARK_SATELLITE_FETCH");
    if (skip != nullptr && std::strcmp(skip, "0") == 0) return false;
    const char *kind = map_satellite ? "sat" : "dark";
    char cached[256]{};
    std::snprintf(cached, sizeof(cached),
                  "/tmp/lilyshark-%s-%.3f_%.3f_z%d.rgb565",
                  kind, cell_lat, cell_lon, map_zoom);
    char command[768]{};
    std::snprintf(command, sizeof(command),
                  "python3 scripts/fetch_satellite_map.py --lat %.6f --lon %.6f "
                  "--zoom %d --style %s --width %d --height %d --out %s >/dev/null 2>&1",
                  cell_lat, cell_lon, map_zoom,
                  map_satellite ? "satellite" : "dark",
                  kSatelliteWidth, kSatelliteHeight, cached);
    return std::system(command) == 0 && load_map_pixels_from_file(cached, dest);
#else
    (void)cell_lat;
    (void)cell_lon;
    (void)dest;
    return false;
#endif
}

#if defined(LILYSHARK_DEVICE)
/// Cover the view with baked imagery even when the view has walked away from
/// the tile it was baked for.
///
/// A tile is a fixed 320x204 window on the ground, so the deeper the zoom the
/// less ground it spans: at z20 it is 37 m across. Standing 46 m from where
/// the tiles were baked put every fine tile entirely off screen and the map
/// fell back to a bare chart. This walks out to coarser zooms until it finds a
/// tile wide enough to contain the view, then magnifies it into place. Coarser
/// means blurrier, never blank.
bool blit_baked_coverage(std::uint16_t *pixels, double view_lat, double view_lon,
                         double mpp, int *used_zoom = nullptr) noexcept
{
    if (pixels == nullptr || !::lilyshark::hasBakedMapTiles()) return false;
    const char *kind = map_chart ? "cht" : (map_satellite ? "sat" : "dark");
    if (map_chart) return false;

    const double baked_lat = ::lilyshark::bakedMapTileLat();
    const double baked_lon = ::lilyshark::bakedMapTileLon();
    const double lat_rad = view_lat * 0.017453292519943295;
    // Offset of the tile centre from the view centre, in metres.
    const double de = (baked_lon - view_lon) * 111320.0 * std::cos(lat_rad);
    const double dn = (baked_lat - view_lat) * 110540.0;

    const double view_half_w = mpp * kSatelliteWidth * 0.5;
    const double view_half_h = mpp * kSatelliteHeight * 0.5;

    for (int zoom = map_zoom; zoom >= kMapZoomMin; --zoom) {
        const std::uint16_t *tile =
            ::lilyshark::bakedMapTile(kind, baked_lat, baked_lon, zoom);
        if (tile == nullptr) continue;
        const double tile_mpp = map_meters_per_pixel_at(view_lat, zoom);
        const double tile_half_w = tile_mpp * kSatelliteWidth * 0.5;
        const double tile_half_h = tile_mpp * kSatelliteHeight * 0.5;
        // Require the tile to contain the whole view, not merely overlap it,
        // so the screen never ends up half imagery and half nothing.
        if (std::fabs(de) + view_half_w > tile_half_w) continue;
        if (std::fabs(dn) + view_half_h > tile_half_h) continue;

        // The source column for a screen column does not depend on the row.
        // Computed per pixel this was 65 280 double divisions and lrounds a
        // frame, on a chip with no hardware double; per axis it is 524.
        std::array<int, static_cast<std::size_t>(kSatelliteWidth)> source_x{};
        for (lv_coord_t x = 0; x < kSatelliteWidth; ++x) {
            const double east_m =
                (static_cast<double>(x) - static_cast<double>(kSatelliteWidth) * 0.5) * mpp;
            source_x[static_cast<std::size_t>(x)] = static_cast<int>(std::lround(
                static_cast<double>(kSatelliteWidth) * 0.5 + (east_m - de) / tile_mpp));
        }
        for (lv_coord_t y = 0; y < kSatelliteHeight; ++y) {
            const double north_m = (static_cast<double>(kSatelliteHeight) * 0.5 -
                                    static_cast<double>(y)) * mpp;
            const int sy = static_cast<int>(std::lround(
                static_cast<double>(kSatelliteHeight) * 0.5 - (north_m - dn) / tile_mpp));
            if (sy < 0 || sy >= kSatelliteHeight) continue;
            const std::uint16_t *source_row =
                tile + static_cast<std::size_t>(sy) * kSatelliteWidth;
            std::uint16_t *dest_row = pixels + static_cast<std::size_t>(y) * kSatelliteWidth;
            for (lv_coord_t x = 0; x < kSatelliteWidth; ++x) {
                const int sx = source_x[static_cast<std::size_t>(x)];
                if (sx < 0 || sx >= kSatelliteWidth) continue;
                dest_row[static_cast<std::size_t>(x)] =
                    source_row[static_cast<std::size_t>(sx)];
            }
        }
        if (used_zoom != nullptr) *used_zoom = zoom;
        return true;
    }
    return false;
}
#endif

bool ensure_field_map(double latitude_degrees, double longitude_degrees) noexcept
{
    std::uint16_t *pixels = satellite_pixel_ptr();
    if (pixels == nullptr) return false;
    const char *kind = map_chart ? "cht" : (map_satellite ? "sat" : "dark");
    const double mpp = map_meters_per_pixel(latitude_degrees);
    const double lat_rad = latitude_degrees * 0.017453292519943295;
    const double m_per_lon = 111320.0 * std::cos(lat_rad);
    const int qe = static_cast<int>(std::lround((longitude_degrees * m_per_lon) / mpp));
    const int qn = static_cast<int>(std::lround((latitude_degrees * 110540.0) / mpp));
    char key[56]{};
    std::snprintf(key, sizeof(key), "%d_%d_z%d_%s", qe, qn, map_zoom, kind);
    if (satellite_ready && std::strcmp(key, satellite_cache_key) == 0) {
        return map_using_imagery;
    }

    map_using_imagery = false;
    map_imagery_edge = false;
    if (map_chart) {
        paint_field_pixels(pixels, latitude_degrees, longitude_degrees, mpp);
        std::snprintf(satellite_cache_key, sizeof(satellite_cache_key), "%s", key);
        satellite_ready = true;
        return false;
    }

    const double cell_lat = map_cell_coord(latitude_degrees);
    const double cell_lon = map_cell_coord(longitude_degrees);
    std::uint16_t *scratch = satellite_scratch_ptr();
    if (scratch == nullptr) {
        paint_field_pixels(pixels, latitude_degrees, longitude_degrees, mpp);
        if (try_load_map_cell(cell_lat, cell_lon, pixels) ||
            fetch_map_cell(cell_lat, cell_lon, pixels)) {
            map_using_imagery = true;
        }
        std::snprintf(satellite_cache_key, sizeof(satellite_cache_key), "%s", key);
        satellite_ready = true;
        return map_using_imagery;
    }

    // Imagery that covers the whole frame is tried before anything is drawn.
    // The field chart underneath is a 320x204 pass of layered value noise in
    // double precision, and the ESP32-S3 has no hardware for doubles -- around
    // a quarter of a million emulated float operations. Painting it beneath
    // imagery that hides every pixel of it was the most expensive thing a
    // redraw did, and a redraw happens on every tap, zoom step and pan. That
    // is the whole of the "the map is laggy when I press the buttons".
    //
    // The card outranks flash: it is the only imagery that follows you off the
    // baked spot.
    bool card_covered_everything = false;
    if (blit_map_card(pixels, scratch, latitude_degrees, longitude_degrees, map_zoom,
                      &card_covered_everything) &&
        card_covered_everything) {
        map_using_imagery = true;
        std::snprintf(satellite_cache_key, sizeof(satellite_cache_key), "%s", key);
        satellite_ready = true;
        return true;
    }
#if defined(LILYSHARK_DEVICE)
    {
        int covered_zoom = 0;
        if (blit_baked_coverage(pixels, latitude_degrees, longitude_degrees, mpp,
                                &covered_zoom)) {
            map_using_imagery = true;
            // Only an edge if it had to reach for a coarser tile to fill the view.
            map_imagery_edge = covered_zoom != map_zoom;
            std::snprintf(satellite_cache_key, sizeof(satellite_cache_key), "%s", key);
            satellite_ready = true;
            return true;
        }
    }
#endif

    // Nothing covers the whole frame, so the chart earns its cost here.
    paint_field_pixels(pixels, latitude_degrees, longitude_degrees, mpp);
    if (blit_map_card(pixels, scratch, latitude_degrees, longitude_degrees, map_zoom,
                      nullptr)) {
        map_using_imagery = true;
        map_imagery_edge = true;
    }

    if (!try_load_map_cell(cell_lat, cell_lon, scratch)) {
        (void)fetch_map_cell(cell_lat, cell_lon, scratch);
    }

    const auto blit_cell = [&](double tlat, double tlon) noexcept {
        // Where it lands first, and only then whether to pay for it. Loading a
        // cell can magnify a whole 320x204 tile, and at deep zoom every one of
        // the eight neighbours is off screen -- cells sit 55 m to 87 m apart
        // while the screen spans 37 m. Deciding after the fact meant eight
        // full-frame magnifies and eight full-frame blits per redraw, all of
        // it painting nothing, on every single tap.
        const int offset_x = static_cast<int>(std::lround(
            ((tlon - longitude_degrees) * m_per_lon) / mpp));
        const int offset_y = static_cast<int>(std::lround(
            ((latitude_degrees - tlat) * 110540.0) / mpp));
        if (offset_x <= -kSatelliteWidth || offset_x >= kSatelliteWidth) return;
        if (offset_y <= -kSatelliteHeight || offset_y >= kSatelliteHeight) return;
        if (!try_load_map_cell(tlat, tlon, scratch)) return;
        blit_map_tile(scratch, pixels, offset_x, offset_y);
        map_using_imagery = true;
        if (offset_x != 0 || offset_y != 0) map_imagery_edge = true;
    };
    for (int dlat = -1; dlat <= 1; ++dlat) {
        for (int dlon = -1; dlon <= 1; ++dlon) {
            if (dlat == 0 && dlon == 0) continue;
            blit_cell(cell_lat + static_cast<double>(dlat) * 0.001,
                      cell_lon + static_cast<double>(dlon) * 0.001);
        }
    }
#if defined(LILYSHARK_DEVICE)
    // Cells are 0.001 deg (~55 m at this latitude) but a tile covers well over
    // a kilometre, so imagery baked for one cell still fills the screen from
    // several cells away. Try it wherever the view is: blit_cell georeferences
    // it by its own centre, and blit_map_tile clips it if it lands off screen.
    blit_cell(::lilyshark::bakedMapTileLat(), ::lilyshark::bakedMapTileLon());
#endif
    blit_cell(cell_lat, cell_lon);

    std::snprintf(satellite_cache_key, sizeof(satellite_cache_key), "%s", key);
    satellite_ready = true;
    return map_using_imagery;
}

#if !defined(LILYSHARK_DEVICE)
bool ensure_satellite_map(double latitude_degrees, double longitude_degrees) noexcept
{
    return ensure_field_map(latitude_degrees, longitude_degrees);
}

double satellite_meters_per_pixel(double latitude_degrees) noexcept
{
    return map_meters_per_pixel(latitude_degrees);
}
#endif
#endif

void draw_field_chart(lv_obj_t *parent, lv_coord_t top, lv_coord_t bottom,
                      double origin_lat, double origin_lon,
                      double meters_per_pixel) noexcept
{
    const lv_coord_t width = 320;
    const lv_coord_t height = bottom - top;
    const lv_coord_t cx = 160;
    const lv_coord_t cy = top + height / 2;
    theme::rect(parent, 0, top, width, height,
                (map_satellite && !map_chart) ? lv_color_hex(0x2A3A18) : lv_color_hex(0x0A1018));
    const double lat_rad = origin_lat * 0.017453292519943295;
    const double origin_east = origin_lon * 111320.0 * std::cos(lat_rad);
    const double origin_north = origin_lat * 110540.0;
    const double cell = 120.0;
    const double left = origin_east - static_cast<double>(cx) * meters_per_pixel;
    const double right = origin_east + static_cast<double>(cx) * meters_per_pixel;
    const double north = origin_north + static_cast<double>(cy - top) * meters_per_pixel;
    const double south = origin_north - static_cast<double>(bottom - cy) * meters_per_pixel;
    if (meters_per_pixel > 0.1) {
        const int x0 = static_cast<int>(std::floor(left / cell));
        const int x1 = static_cast<int>(std::ceil(right / cell));
        const int y0 = static_cast<int>(std::floor(south / cell));
        const int y1 = static_cast<int>(std::ceil(north / cell));
        for (int gy = y0; gy <= y1; ++gy) {
            for (int gx = x0; gx <= x1; ++gx) {
                const std::uint32_t cell_hash = map_hash2(gx, gy);
                const lv_coord_t px = cx + static_cast<lv_coord_t>(
                    ((static_cast<double>(gx) * cell - origin_east) / meters_per_pixel));
                const lv_coord_t py = cy - static_cast<lv_coord_t>(
                    ((static_cast<double>(gy) * cell - origin_north) / meters_per_pixel));
                const lv_coord_t block = static_cast<lv_coord_t>(cell / meters_per_pixel);
                if (block < 6 || px > width || py > bottom || px + block < 0 || py + block < top) {
                    continue;
                }
                const bool park = ((cell_hash >> 4U) % 11U) == 0U;
                const bool water = ((cell_hash >> 8U) % 17U) == 0U;
                if (water) {
                    theme::rect(parent, px, py, block, block,
                                (map_satellite && !map_chart) ? lv_color_hex(0x163038)
                                                              : lv_color_hex(0x0C1828));
                } else if (park) {
                    theme::rect(parent, px + 2, py + 2,
                                block > 6 ? block - 4 : block,
                                block > 6 ? block - 4 : block,
                                (map_satellite && !map_chart) ? lv_color_hex(0x2E4E24)
                                                              : lv_color_hex(0x0C1C16));
                }
            }
        }
        const lv_color_t road = (map_satellite && !map_chart) ? lv_color_hex(0x3A3834)
                                                             : lv_color_hex(0x4E5868);
        for (int gx = x0; gx <= x1; ++gx) {
            const lv_coord_t px = cx + static_cast<lv_coord_t>(
                ((static_cast<double>(gx) * cell - origin_east) / meters_per_pixel));
            if (px < 0 || px >= width) continue;
            theme::rect(parent, px, top, 1, height, road);
        }
        for (int gy = y0; gy <= y1; ++gy) {
            const lv_coord_t py = cy - static_cast<lv_coord_t>(
                ((static_cast<double>(gy) * cell - origin_north) / meters_per_pixel));
            if (py < top || py >= bottom) continue;
            theme::rect(parent, 0, py, width, 1, road);
        }
    }
    const double ring_m[] = {100.0, 200.0, 500.0, 1000.0, 2000.0};
    for (double meters : ring_m) {
        if (meters_per_pixel < 0.1) break;
        const lv_coord_t radius = static_cast<lv_coord_t>(meters / meters_per_pixel);
        if (radius < 16 || radius > 130) continue;
        draw_map_ring(parent, cx, cy, radius, (map_satellite && !map_chart)
                                                 ? lv_color_hex(0x6A6040)
                                                 : lv_color_hex(0x2A4050));
        char label[12]{};
        if (meters >= 1000.0) std::snprintf(label, sizeof(label), "%.0fkm", meters / 1000.0);
        else std::snprintf(label, sizeof(label), "%.0fm", meters);
        put_label(parent, label, cx + 4, cy - radius - 1, theme::text(), &font_pixel_6x8);
    }
}

/// The layer currently on screen. The chip is labelled with this and tapping
/// it moves to the next, so one control replaces three and none of them is a
/// word you have to decode.
const char *current_map_layer_name() noexcept
{
    return map_chart ? "GRID" : (map_satellite ? "SAT" : "ROADS");
}

/// Text that reads over imagery without a black bar behind it. The map is the
/// whole point of the map screen, and the full-width plates these replace were
/// taking a seventh of the picture between them.
void put_map_label(lv_obj_t *parent, const char *text, lv_coord_t x, lv_coord_t y,
                   lv_coord_t width, lv_color_t color, const lv_font_t *font) noexcept
{
    if (text == nullptr || text[0] == '\0') return;
    const lv_color_t shadow = lv_color_hex(0x000000);
    put_clipped_label(parent, text, x - 1, y, width, shadow, font);
    put_clipped_label(parent, text, x + 1, y, width, shadow, font);
    put_clipped_label(parent, text, x, y - 1, width, shadow, font);
    put_clipped_label(parent, text, x, y + 1, width, shadow, font);
    put_clipped_label(parent, text, x, y, width, color, font);
}

void plot_field_map(lv_obj_t *parent, const MapMark *marks, std::size_t mark_count,
                    const char *fix_line, const char *detail_line,
                    double meters_per_pixel = 0.0,
                    double origin_lat = 0.0, double origin_lon = 0.0,
                    double you_accuracy_m = 0.0, bool muted = false) noexcept
{
    constexpr lv_coord_t top = 22;
    constexpr lv_coord_t bottom = 226;
    constexpr lv_coord_t width = 320;
    constexpr lv_coord_t height = bottom - top;
    const lv_coord_t cx = 160;
    const lv_coord_t cy = top + height / 2;
    const bool georef = meters_per_pixel > 0.1;
    map_last_origin_lat = origin_lat;
    map_last_origin_lon = origin_lon;
    map_last_origin_valid = georef && !muted;
    bool drew_tiles = false;
    if (muted) {
        map_using_imagery = false;
        theme::rect(parent, 0, top, width, height, lv_color_hex(0x0A1018));
        lv_coord_t step = georef ? static_cast<lv_coord_t>(200.0 / meters_per_pixel)
                                 : static_cast<lv_coord_t>(40);
        if (step < 18) step = 18;
        if (step > 72) step = 72;
        add_grid(parent, 0, top, width, height, step, step);
    } else {
#if !defined(LILYSHARK_DEVICE) || defined(ESP_PLATFORM)
        std::uint16_t *pixels = satellite_pixel_ptr();
        if (georef && satellite_ready && pixels != nullptr) {
            lv_obj_t *canvas = lv_canvas_create(parent);
            theme::reset(canvas);
            lv_canvas_set_buffer(canvas, pixels, kSatelliteWidth, kSatelliteHeight,
                                 LV_COLOR_FORMAT_RGB565);
            lv_obj_set_pos(canvas, 0, top);
            drew_tiles = true;
        }
#endif
        if (!drew_tiles) {
            draw_field_chart(parent, top, bottom, origin_lat, origin_lon, meters_per_pixel);
        }
    }

    // The N/S/E/W boxes and the black bands they sat in are gone. At the zooms
    // this map is actually used at -- one house fills the screen at z20 -- a
    // cardinal tick tells an operator nothing they did not already know, and
    // between them the chrome was eating a seventh of the picture.
    if (map_panned) {
        // Worth drawing only once the view has left the operator: it marks
        // where the screen is centred, not where anybody is standing.
        theme::rect(parent, cx - 8, cy, 17, 1, theme::pink());
        theme::rect(parent, cx, cy - 8, 1, 17, theme::pink());
    }

    double bar_m = 200.0;
    if (georef && meters_per_pixel > 0.0) {
        // A 1-2-5 series taken from the scale actually on screen, so the bar
        // is truthful at every zoom. The fixed candidate list this replaces
        // bottomed out at 50 m: past about z16 nothing fitted the pixel
        // window and it fell through to a hardcoded "200 M" printed over a
        // bar that really measured 34 m at z18 and 8 m at z20.
        const double target = 56.0 * meters_per_pixel;
        const double decade = std::pow(10.0, std::floor(std::log10(target)));
        const double normalised = target / decade;
        const double step = normalised < 1.5 ? 1.0
                          : normalised < 3.5 ? 2.0
                          : normalised < 7.5 ? 5.0
                                             : 10.0;
        bar_m = step * decade;
        if (bar_m < 1.0) bar_m = 1.0;
    } else {
        bar_m = 4800.0 / static_cast<double>(1 << (map_zoom - kMapZoomMin));
        if (bar_m < 200.0) bar_m = 200.0;
    }
    lv_coord_t bar_px = georef ? static_cast<lv_coord_t>(bar_m / meters_per_pixel)
                               : static_cast<lv_coord_t>(56);
    // The 1-2-5 choice lands between about 38 and 75 px by construction, so
    // these bounds are a guard against a degenerate scale, not a clamp that
    // routinely fires and puts the label out of step with the bar again.
    if (bar_px < 18) bar_px = 18;
    if (bar_px > 96) bar_px = 96;
    char scale[16]{};
    format_map_range(scale, sizeof(scale), bar_m);
    const lv_coord_t scale_w = static_cast<lv_coord_t>(std::strlen(scale) * 6);
    theme::rect(parent, 7, bottom - 13, bar_px + 2, 4, lv_color_hex(0x000000));
    theme::rect(parent, 8, bottom - 12, bar_px, 2, theme::text());
    put_map_label(parent, scale, 14 + bar_px, bottom - 18, 80, theme::text(),
                  &font_mono_semibold_12);

    if (fix_line != nullptr && fix_line[0] != '\0') {
        put_map_label(parent, fix_line, 8, bottom - 32, 240, theme::lime(),
                      &font_mono_semibold_12);
    }
    char hud[24]{};
    if (detail_line != nullptr && detail_line[0] != '\0') {
        std::snprintf(hud, sizeof(hud), "Z%d %s%s", map_zoom, detail_line,
                      map_using_imagery ? (map_imagery_edge ? "  BLURRY" : "")
                                        : "  NO IMAGERY");
    } else {
        std::snprintf(hud, sizeof(hud), "Z%d%s", map_zoom,
                      map_using_imagery ? (map_imagery_edge ? "  BLURRY" : "")
                                        : "  NO IMAGERY");
    }
    if (hud[0] != '\0') {
        // Top-left on its own. The position sits in the bottom stack, so the
        // two can each be as long as they need to be.
        put_map_label(parent, hud, 8, top + 4, 200, theme::text(),
                      &font_mono_semibold_12);
    }

    const MapMark *you_mark = nullptr;
    const MapMark *sel_mark = nullptr;
    if (marks != nullptr) {
        for (std::size_t index = 0; index < mark_count; ++index) {
            if (marks[index].you) you_mark = &marks[index];
            else if (marks[index].selected) sel_mark = &marks[index];
        }
    }
    char bearing_line[36]{};
    if (you_mark != nullptr && sel_mark != nullptr) {
        const double de = sel_mark->east_m - you_mark->east_m;
        const double dn = sel_mark->north_m - you_mark->north_m;
        char range[12]{};
        format_map_range(range, sizeof(range), std::hypot(de, dn));
        const char *name = sel_mark->name[0] != '\0' ? sel_mark->name : "NODE";
        std::snprintf(bearing_line, sizeof(bearing_line), "%s  %s  %03.0f",
                      name, range, map_bearing_deg(de, dn));
    } else if (you_accuracy_m > 0.5) {
        char acc[12]{};
        format_map_range(acc, sizeof(acc), you_accuracy_m);
        std::snprintf(bearing_line, sizeof(bearing_line), "YOU  +/-%s", acc);
    }
    if (bearing_line[0] != '\0' && !map_popup.open) {
        put_map_label(parent, bearing_line, 8, bottom - 46, 256, theme::pink(),
                      &font_mono_semibold_12);
    }

    if (muted) {
        put_centered_label(parent, "NO FIX", 108, theme::amber(), &font_pixel_18x24);
    }

    const auto project = [georef, cx, cy, meters_per_pixel](const MapMark &mark,
                                                            lv_coord_t &x,
                                                            lv_coord_t &y) {
        x = cx;
        y = cy;
        if (georef) {
            x = cx + static_cast<lv_coord_t>(mark.east_m / meters_per_pixel);
            y = cy - static_cast<lv_coord_t>(mark.north_m / meters_per_pixel);
        }
    };
    lv_coord_t you_x = cx;
    lv_coord_t you_y = cy;
    if (you_mark != nullptr) {
        project(*you_mark, you_x, you_y);
        if (georef && you_accuracy_m > 0.5) {
            lv_coord_t radius =
                static_cast<lv_coord_t>(you_accuracy_m / meters_per_pixel);
            if (radius < 12) radius = 12;
            if (radius <= 90) {
                const lv_coord_t outer = radius * 2;
                if (outer <= 90) {
                    draw_map_ring(parent, you_x, you_y, outer, lv_color_hex(0x000000), 2);
                    draw_map_ring(parent, you_x, you_y, outer, theme::text_muted(), 1);
                }
                draw_map_ring(parent, you_x, you_y, radius, lv_color_hex(0x000000), 3);
                draw_map_ring(parent, you_x, you_y, radius, theme::pink(), 2);
            }
        }
    }
    // Only while a node card is actually open. A line permanently slicing the
    // map corner to corner towards something off screen is noise.
    if (map_popup.open && you_mark != nullptr && sel_mark != nullptr && georef) {
        lv_coord_t sel_x = cx;
        lv_coord_t sel_y = cy;
        project(*sel_mark, sel_x, sel_y);
        const bool you_in = you_x >= 4 && you_x <= 272 && you_y >= top + 28 &&
                            you_y <= bottom - 20;
        const bool sel_in = sel_x >= 4 && sel_x <= 272 && sel_y >= top + 28 &&
                            sel_y <= bottom - 20;
        if (you_in || sel_in) {
            lv_coord_t x0 = you_x;
            lv_coord_t y0 = you_y;
            lv_coord_t x1 = sel_x;
            lv_coord_t y1 = sel_y;
            if (x0 < 4) x0 = 4;
            if (x0 > 272) x0 = 272;
            if (x1 < 4) x1 = 4;
            if (x1 > 272) x1 = 272;
            if (y0 < top + 28) y0 = top + 28;
            if (y0 > bottom - 20) y0 = bottom - 20;
            if (y1 < top + 28) y1 = top + 28;
            if (y1 > bottom - 20) y1 = bottom - 20;
            draw_map_segment(parent, x0, y0, x1, y1, theme::pink());
            if (!sel_in) {
                draw_map_chevron(parent, x1, y1,
                                 sel_mark->east_m - you_mark->east_m,
                                 sel_mark->north_m - you_mark->north_m);
            }
        }
    }

    map_hit_count = 0;
    struct LabelBox {
        lv_coord_t x = 0;
        lv_coord_t y = 0;
        lv_coord_t w = 0;
    };
    std::array<LabelBox, 9> labels{};
    std::size_t label_count = 0;
    for (std::size_t index = 0; index < mark_count; ++index) {
        const MapMark &mark = marks[index];
        lv_coord_t x = cx;
        lv_coord_t y = cy;
        project(mark, x, y);
        if (georef) {
            if (x < 4 || x > 272 || y < top + 28 || y > bottom - 20) continue;
        }
        if (map_hit_count < map_hits.size()) {
            map_hits[map_hit_count++] = {x, y, mark.node_index};
        }
        const char *tag = mark.you ? "YOU" : mark.name;
        const lv_coord_t tag_w = static_cast<lv_coord_t>(std::strlen(tag) * 6);
        lv_coord_t tag_x = x + 7;
        lv_coord_t tag_y = ((index % 2U) == 0U) ? y - 5 : y + 5;
        if (tag_x + tag_w > 270) tag_x = x - tag_w - 7;
        if (tag_y < top + 30) tag_y = y + 5;
        if (tag_y > bottom - 16) tag_y = y - 13;
        bool collide = false;
        for (std::size_t prior = 0; prior < label_count; ++prior) {
            const LabelBox &box = labels[prior];
            const lv_coord_t dx = tag_x > box.x ? tag_x - box.x : box.x - tag_x;
            const lv_coord_t dy = tag_y > box.y ? tag_y - box.y : box.y - tag_y;
            if (dx < tag_w + 4 && dy < 10) {
                collide = true;
                break;
            }
        }
        if (mark.you) {
            // A crosshair, not a block. At z20 a 9 px filled square covers
            // about a metre of ground -- precisely the ground the operator
            // opened the map to look at.
            theme::rect(parent, x - 7, y - 1, 15, 3, lv_color_hex(0x000000));
            theme::rect(parent, x - 1, y - 7, 3, 15, lv_color_hex(0x000000));
            theme::rect(parent, x - 6, y, 13, 1, theme::pink());
            theme::rect(parent, x, y - 6, 1, 13, theme::pink());
            theme::rect(parent, x - 1, y - 1, 3, 3, theme::pink());
        } else {
            const lv_color_t color = mark.selected ? theme::pink() : theme::lime();
            theme::rect(parent, x - 3, y - 3, 7, 7, lv_color_hex(0x000000));
            theme::rect(parent, x - 2, y - 2, 5, 5, color);
        }
        if (!collide && !mark.you) {
            put_map_label(parent, tag, tag_x, tag_y, tag_w + 8,
                          mark.selected ? theme::pink() : theme::lime(),
                          &font_pixel_6x8);
            if (label_count < labels.size()) {
                labels[label_count++] = {tag_x, tag_y, tag_w};
            }
        }
    }

    const auto chip = [parent](lv_coord_t x, lv_coord_t y, const char *label, bool selected,
                               bool enabled = true) {
        const lv_color_t ink = !enabled ? theme::text_muted() :
                               (selected ? theme::pink() : theme::text());
        theme::rect(parent, x, y, kMapCtrlW, kMapCtrlH,
                    selected && enabled ? lv_color_hex(0x180810) : lv_color_hex(0x000000));
        draw_outline_rect(parent, x, y, kMapCtrlW, kMapCtrlH, ink);
        const lv_coord_t text_w = static_cast<lv_coord_t>(std::strlen(label) * 6);
        put_label(parent, label, x + (kMapCtrlW - text_w) / 2, y + 7, ink, &font_pixel_6x8);
    };
    chip(kMapCtrlX, kMapPlusY, "+", false, map_zoom < kMapZoomMax);
    chip(kMapCtrlX, kMapMinusY, "-", false, map_zoom > kMapZoomMin);
    chip(kMapCtrlX, kMapSatY, current_map_layer_name(), false);
    // Only offered when it would do something.
    if (map_panned) chip(kMapCtrlX, kMapMapY, "HERE", false);

    // The card is drawn after every mark and label, so it is opaque: the
    // YOU marker and the peer dots used to punch through it.
    if (map_popup.open) {
        theme::rect(parent, kPopX, kPopY, kPopW, kPopH, lv_color_hex(0x05080C));
        draw_outline_rect(parent, kPopX, kPopY, kPopW, kPopH, theme::pink());

        put_clipped_label(parent, map_popup.name[0] != '\0' ? map_popup.name : "NODE",
                          kPopX + 10, kPopY + 8, kPopCloseX - kPopX - 18, theme::pink(),
                          &font_condensed_bold_16);
        // Close is a real target, not a decoration: 22x18 with the glyph centred.
        draw_outline_rect(parent, kPopCloseX, kPopCloseY, kPopCloseW, 18, theme::text_muted());
        put_label(parent, "X", kPopCloseX + 8, kPopCloseY + 5, theme::text_muted(),
                  &font_pixel_6x8);

        char id_line[24]{};
        std::snprintf(id_line, sizeof(id_line), "!%08lx",
                      static_cast<unsigned long>(map_popup.id));
        put_label(parent, id_line, kPopX + 10, kPopY + 30, theme::text_muted(),
                  &font_pixel_6x8);

        char range_line[40]{};
        if (map_popup.has_position) {
            char range[12]{};
            format_map_range(range, sizeof(range), map_popup.range_m);
            // "BRG" is chart shorthand. The card has the width for the word.
            std::snprintf(range_line, sizeof(range_line), "%s AWAY  BEARING %03.0f",
                          range, map_popup.bearing_deg);
        } else {
            std::snprintf(range_line, sizeof(range_line), "NO POSITION REPORTED");
        }
        put_clipped_label(parent, range_line, kPopX + 10, kPopY + 44, kPopW - 20,
                          theme::lime(), &font_mono_semibold_12);

        if (map_popup.has_position) {
            char coord_line[44]{};
            std::snprintf(coord_line, sizeof(coord_line), "%.5f %c  %.5f %c",
                          map_popup.lat < 0.0 ? -map_popup.lat : map_popup.lat,
                          map_popup.lat < 0.0 ? 'S' : 'N',
                          map_popup.lon < 0.0 ? -map_popup.lon : map_popup.lon,
                          map_popup.lon < 0.0 ? 'W' : 'E');
            put_clipped_label(parent, coord_line, kPopX + 10, kPopY + 62, kPopW - 20,
                              theme::text(), &font_pixel_6x8);
        }

        draw_outline_rect(parent, kPopMsgX, kPopBtnY, kPopMsgW, kPopBtnH, theme::pink());
        put_label(parent, "MESSAGE", kPopMsgX + 24, kPopBtnY + 7, theme::pink(),
                  &font_pixel_6x8);
        draw_outline_rect(parent, kPopTelX, kPopBtnY, kPopTelW, kPopBtnH, theme::cyan());
        put_label(parent, "TELEMETRY", kPopTelX + 26, kPopBtnY + 7, theme::cyan(),
                  &font_pixel_6x8);
    }
}

/// How long since a node was heard, as a colour. Whether a neighbour is still
/// in range is the question the nodes list exists to answer, and an age in
/// muted grey only answers it if you stop and read the number.
lv_color_t node_age_color_seconds(std::uint64_t age_seconds) noexcept
{
    if (age_seconds < 300ULL) return theme::lime();
    if (age_seconds < 1800ULL) return theme::amber();
    return theme::fault();
}

#if defined(LILYSHARK_DEVICE)
void format_node(char *output, std::size_t capacity, const DecodedPacket &packet,
                 DecodedField field) noexcept
{
    if(!packet.hasField(field)) {
        std::snprintf(output, capacity, "--");
        return;
    }
    const std::uint32_t value = field == FieldSource ? packet.source : packet.destination;
    if(value == 0xffffffffU) std::snprintf(output, capacity, "ALL");
    else std::snprintf(output, capacity, "%08lX", static_cast<unsigned long>(value));
}

void format_radio_field_node(char *output, std::size_t capacity, const DecodedPacket &packet,
                             DecodedField field) noexcept
{
    if(!packet.hasField(field)) {
        std::snprintf(output, capacity, "RF");
        return;
    }
    format_node(output, capacity, packet, field);
}

void format_capture_time(char *output, std::size_t capacity, std::uint64_t timestamp_us) noexcept
{
    const std::uint64_t seconds = timestamp_us / 1000000ULL;
    const std::uint64_t tenths = (timestamp_us / 100000ULL) % 10ULL;
    std::snprintf(output, capacity, "%02llu:%02llu.%llu",
                  static_cast<unsigned long long>((seconds / 60ULL) % 100ULL),
                  static_cast<unsigned long long>(seconds % 60ULL),
                  static_cast<unsigned long long>(tenths));
}

struct LiveNodeSummary {
    ProtocolId protocol = ProtocolId::Unknown;
    std::uint32_t id = 0;
    std::uint64_t last_seen_us = 0;
    std::int32_t snr_sum_x10 = 0;
    std::int16_t latest_snr_x10 = 0;
    std::int16_t latest_rssi_x10 = 0;
    std::uint16_t frames = 0;
    std::uint16_t crc_errors = 0;
    std::uint8_t hops = 0;
    bool has_position = false;
    double latitude_degrees = 0.0;
    double longitude_degrees = 0.0;
    char label[9]{};
};

/// A frame is evidence of a *peer* only if we did not send it. The device
/// beacons its own position and NodeInfo, and those frames are ingested like
/// any other, so without this every device lists itself as a node and draws a
/// second dot on top of YOU.
bool frameIsFromAnotherNode(const FrameRecord &record) noexcept
{
    if(record.raw.rf.direction == FrameDirection::Transmit) return false;
    if(record.decoded.source == localMeshtasticNodeNum()) return false;
    return true;
}

std::size_t collect_live_nodes(std::array<LiveNodeSummary, 8> &summaries) noexcept
{
    std::size_t count = 0;
    const auto &store = capture_runtime.frames();

    // Preserve the newest-node policy while allowing the selected identities
    // to be replayed chronologically below. CRC-invalid records never create
    // an identity.
    for(std::size_t offset = 0; offset < store.size(); ++offset) {
        const FrameRecord *record = store.newest(offset);
        if(record == nullptr || !contributesToNodeSummary(*record)) continue;
        if(!frameIsFromAnotherNode(*record)) continue;

        std::size_t index = 0;
        for(; index < count; ++index) {
            if(summaries[index].protocol == record->decoded.protocol &&
               summaries[index].id == record->decoded.source) break;
        }
        if(index == count) {
            if(count == summaries.size()) continue;
            summaries[index].protocol = record->decoded.protocol;
            summaries[index].id = record->decoded.source;
            ++count;
        }
    }

    for(std::size_t offset = 0; offset < store.size(); ++offset) {
        const FrameRecord *record = store.at(offset);
        if(record == nullptr) continue;

        std::size_t index = 0;
        for(; index < count; ++index) {
            if(summaries[index].protocol == record->decoded.protocol &&
               summaries[index].id == record->decoded.source) break;
        }
        if(index == count) continue;

        LiveNodeSummary &summary = summaries[index];
        if(contributesToNodeSummary(*record) && frameIsFromAnotherNode(*record)) {
            summary.last_seen_us = record->raw.rf.timestamp_us;
            summary.latest_snr_x10 = record->raw.rf.snr_db_x10;
            summary.latest_rssi_x10 = record->raw.rf.rssi_dbm_x10;
            summary.snr_sum_x10 += record->raw.rf.snr_db_x10;
            if (record->decoded.hasField(FieldHopStart) &&
                record->decoded.hop_start >= record->decoded.hop_limit) {
                const unsigned hops = record->decoded.hop_start - record->decoded.hop_limit;
                summary.hops = static_cast<std::uint8_t>(hops > 3U ? 3U : hops);
            }
            if(summary.frames != UINT16_MAX) ++summary.frames;
            if (record->decoded.protocol == ProtocolId::Meshtastic &&
                record->decoded.hasAttribute(AttributeDefaultKeyReadable) &&
                record->decoded.payload_length > 0U &&
                record->raw.captured_length >=
                    static_cast<std::uint16_t>(record->decoded.payload_offset +
                                               record->decoded.payload_length)) {
                MeshtasticPayload payload{};
                if (readMeshtasticPayload(record->raw.bytes + record->decoded.payload_offset,
                                          record->decoded.payload_length,
                                          record->decoded.source, record->decoded.packet_id,
                                          payload)) {
                    if (payload.has_position) {
                        summary.has_position = true;
                        summary.latitude_degrees = payload.latitude_degrees;
                        summary.longitude_degrees = payload.longitude_degrees;
                    }
                    if (payload.has_names && payload.short_name[0] != '\0') {
                        std::snprintf(summary.label, sizeof(summary.label), "%.8s",
                                      payload.short_name);
                    }
                }
            }
            if (summary.label[0] == '\0') {
                std::snprintf(summary.label, sizeof(summary.label), "%08lX",
                              static_cast<unsigned long>(summary.id));
            }
        } else if(contributesToExistingNodeCrcErrors(*record, summary.frames != 0U,
                                                     summary.protocol, summary.id)) {
            summary.crc_errors = incrementedNodeCrcErrorCount(summary.crc_errors);
        }
    }
    return count;
}

const FrameRecord *find_live_frame(std::uint64_t sequence,
                                   std::size_t *offset_from_newest = nullptr) noexcept
{
    const auto &store = capture_runtime.frames();
    for(std::size_t offset = 0; offset < store.size(); ++offset) {
        const FrameRecord *record = store.newest(offset);
        if(record != nullptr && record->sequence == sequence) {
            if(offset_from_newest != nullptr) *offset_from_newest = offset;
            return record;
        }
    }
    return nullptr;
}

std::size_t resolve_traffic_selection() noexcept
{
    const auto &store = capture_runtime.frames();
    const TrafficFilterSnapshot filtered = trafficFilterSnapshot(store, traffic_filter);
    if(filtered.matching_frames == 0U) {
        traffic_selected_sequence = 0;
        return 0;
    }

    if(traffic_selected_sequence != 0U) {
        for(std::size_t offset = 0U; offset < filtered.matching_frames; ++offset) {
            const FrameRecord *candidate = newestMatchingFrame(store, traffic_filter, offset);
            if(candidate != nullptr && candidate->sequence == traffic_selected_sequence) {
                return offset;
            }
        }
    }

    const std::size_t selected_offset = traffic_selected_sequence == 0U
        ? 0U : filtered.matching_frames - 1U;
    const FrameRecord *fallback = newestMatchingFrame(store, traffic_filter, selected_offset);
    traffic_selected_sequence = fallback == nullptr ? 0 : fallback->sequence;
    return selected_offset;
}

bool move_traffic_selection(int direction) noexcept
{
    const auto &store = capture_runtime.frames();
    const TrafficFilterSnapshot filtered = trafficFilterSnapshot(store, traffic_filter);
    if(filtered.matching_frames == 0U) return false;

    std::size_t selected_offset = resolve_traffic_selection();
    if(direction > 0) {
        selected_offset = (selected_offset + 1U) % filtered.matching_frames;
    } else if(direction < 0) {
        selected_offset = selected_offset == 0U ? filtered.matching_frames - 1U
                                                 : selected_offset - 1U;
    } else {
        return false;
    }
    const FrameRecord *selected = newestMatchingFrame(store, traffic_filter, selected_offset);
    if(selected == nullptr) return false;
    traffic_selected_sequence = selected->sequence;
    return true;
}

bool live_node_matches(const LiveNodeSummary &node, ProtocolId protocol,
                       std::uint32_t id) noexcept
{
    return node.protocol == protocol && node.id == id;
}

std::size_t resolve_node_selection(const std::array<LiveNodeSummary, 8> &live_nodes,
                                   std::size_t count) noexcept
{
    if(count == 0) {
        node_selection_valid = false;
        return 0;
    }
    if(node_selection_valid) {
        for(std::size_t index = 0; index < count; ++index) {
            if(live_node_matches(live_nodes[index], node_selected_protocol, node_selected_id)) {
                return index;
            }
        }
    }
    node_selected_protocol = live_nodes[0].protocol;
    node_selected_id = live_nodes[0].id;
    node_selection_valid = true;
    return 0;
}

bool move_node_selection(int direction) noexcept
{
    std::array<LiveNodeSummary, 8> live_nodes{};
    const std::size_t count = collect_live_nodes(live_nodes);
    if(count == 0) return false;

    std::size_t selected_index = resolve_node_selection(live_nodes, count);
    if(direction > 0) {
        selected_index = (selected_index + 1) % count;
    } else if(direction < 0) {
        selected_index = selected_index == 0 ? count - 1 : selected_index - 1;
    } else {
        return false;
    }
    node_selected_protocol = live_nodes[selected_index].protocol;
    node_selected_id = live_nodes[selected_index].id;
    node_selection_valid = true;
    if (selected_index < nodes_scroll_offset) nodes_scroll_offset = selected_index;
    if (selected_index >= nodes_scroll_offset + kNodesVisible) {
        nodes_scroll_offset = selected_index + 1U - kNodesVisible;
    }
    return true;
}

bool select_current_frame_for_detail() noexcept
{
    const auto &store = capture_runtime.frames();
    if(store.empty()) return false;
    const FrameRecord *record = newestMatchingFrame(
        store, traffic_filter, resolve_traffic_selection());
    if(record == nullptr) return false;
    packet_detail_sequence = record->sequence;
    packet_detail_byte_offset = 0U;
    return true;
}

bool select_current_node_for_detail() noexcept
{
    std::array<LiveNodeSummary, 8> live_nodes{};
    const std::size_t count = collect_live_nodes(live_nodes);
    if(count == 0) return false;
    const LiveNodeSummary &node = live_nodes[resolve_node_selection(live_nodes, count)];
    node_detail_protocol = node.protocol;
    node_detail_id = node.id;
    node_detail_selection_valid = true;
    return true;
}

lv_color_t node_age_color(std::uint64_t timestamp_us) noexcept
{
    const std::uint64_t now_us = static_cast<std::uint64_t>(esp_timer_get_time());
    return node_age_color_seconds(
        now_us > timestamp_us ? (now_us - timestamp_us) / 1000000ULL : 0);
}

void format_age(char *output, std::size_t capacity, std::uint64_t timestamp_us) noexcept
{
    const std::uint64_t now_us = static_cast<std::uint64_t>(esp_timer_get_time());
    const std::uint64_t age_seconds = now_us > timestamp_us ? (now_us - timestamp_us) / 1000000ULL : 0;
    if(age_seconds < 60) {
        std::snprintf(output, capacity, "%lluS", static_cast<unsigned long long>(age_seconds));
    } else if(age_seconds < 3600) {
        std::snprintf(output, capacity, "%lluM", static_cast<unsigned long long>(age_seconds / 60ULL));
    } else {
        std::snprintf(output, capacity, "%lluH", static_cast<unsigned long long>(age_seconds / 3600ULL));
    }
}

void draw_live_node_history(lv_obj_t *parent, const LiveNodeSummary &node, lv_coord_t x,
                            lv_coord_t y, lv_coord_t width, lv_coord_t height,
                            bool use_rssi = false,
                            lv_color_t color = theme::lime()) noexcept
{
    int values[64]{};
    std::size_t sample_count = 0;
    const auto &store = capture_runtime.frames();
    for(std::size_t index = 0; index < store.size() && sample_count < 64U; ++index) {
        const FrameRecord *record = store.at(index);
        if(record != nullptr && record->decoded.hasField(FieldSource) &&
           record->decoded.protocol == node.protocol && record->decoded.source == node.id) {
            values[sample_count++] = use_rssi ? record->raw.rf.rssi_dbm_x10
                                              : record->raw.rf.snr_db_x10;
        }
    }
    if(sample_count == 0) return;
    const int low = use_rssi ? -1250 : -250;
    const int high = use_rssi ? -800 : 50;
    if (width >= 160) {
        draw_field_plot(parent, use_rssi ? 1 : 0, x, y, width, height, values, sample_count,
                        low, high, color, theme::text(), !use_rssi);
        return;
    }
    theme::rect(parent, x, y, width, height, lv_color_hex(0x040C0B));
    if (trace_buffer_index < trace_buffers.size()) {
        auto &points = trace_buffers[trace_buffer_index++];
        for (std::size_t index = 0; index < sample_count; ++index) {
            const int bar = plot_scale(values[index], low, high, height);
            points[index].x = sample_count == 1U ? 0 : static_cast<lv_coord_t>(
                (index * static_cast<std::size_t>(width - 1)) / (sample_count - 1U));
            points[index].y = static_cast<lv_coord_t>(height - 1 - bar);
        }
        lv_obj_t *line = lv_line_create(parent);
        theme::reset(line);
        lv_line_set_points(line, points.data(), static_cast<std::uint32_t>(sample_count));
        lv_obj_set_pos(line, x, y);
        lv_obj_set_size(line, width, height);
        lv_obj_set_style_line_color(line, color, 0);
        lv_obj_set_style_line_width(line, 2, 0);
    }
}

#endif

const char *spectrum_scan_mode_label() noexcept
{
    return spectrum_scan_mode == SpectrumScanMode::FastNarrow ? "FAST NARROW" : "DEEP BAND";
}

bool apply_spectrum_scan_mode(SpectrumScanMode next) noexcept
{
#if defined(LILYSHARK_DEVICE)
    if (radio_service.spectrumStatus().active()) return false;
#else
    if (simulator_spectrum_scanning) return false;
#endif
    if (next == spectrum_scan_mode) return false;
    spectrum_scan_mode = next;
#if defined(LILYSHARK_DEVICE)
    radio_service.clearSpectrumResult();
#else
    simulator_spectrum_partial_points = 0U;
    simulator_spectrum_cancelled = false;
    simulator_spectrum_started_ms = simulator_live_telemetry.elapsedMilliseconds();
#endif
    return true;
}

bool apply_map_layer(bool satellite, bool chart) noexcept
{
    if (chart) {
        if (map_chart) return false;
        map_chart = true;
        return true;
    }
    if (map_satellite == satellite && !map_chart) return false;
    map_satellite = satellite;
    map_chart = false;
    return true;
}

/// SAT -> ROADS -> GRID -> SAT. The chip shows where you are in that cycle.
bool cycle_map_layer() noexcept
{
    if (map_chart) return apply_map_layer(true, false);
    if (map_satellite) return apply_map_layer(false, false);
    return apply_map_layer(false, true);
}

bool apply_timeline_filter(std::size_t next) noexcept
{
    next %= 5U;
    if (next == timeline_filter_selection) return false;
    timeline_filter_selection = next;
    return true;
}

