void sync_nodes_scroll(std::size_t selected, std::size_t count) noexcept
{
    if (count <= kNodesVisible) {
        nodes_scroll_offset = 0;
        return;
    }
    if (selected < nodes_scroll_offset) nodes_scroll_offset = selected;
    if (selected >= nodes_scroll_offset + kNodesVisible) {
        nodes_scroll_offset = selected + 1U - kNodesVisible;
    }
    if (nodes_scroll_offset + kNodesVisible > count) {
        nodes_scroll_offset = count - kNodesVisible;
    }
}

