void build_onboarding_profile(lv_obj_t * parent)
{
    add_setup_header(parent, "PROFILE", "4 / 6");
    const std::size_t count = onboarding_profile_count();
    const std::size_t profile_index = onboarding_profile_index(onboarding_profile_selection);
    const RadioProfile &profile = builtinProfiles()[profile_index];
    char line[64]{};
    put_centered_label(parent, shell_protocol_name(profile.protocol_hint), 28,
                       theme::pink(), &font_pixel_6x8);
    put_centered_label(parent, home_profile_tag(profile), 42, theme::text(),
                       &font_pixel_6x8);
    std::snprintf(line, sizeof(line), "%.3f",
                  static_cast<double>(profile.center_frequency_hz) / 1000000.0);
    put_centered_label(parent, line, 56, theme::cyan(), &font_pixel_18x24);
    put_centered_label(parent, "MHZ", 82, theme::text_muted(), &font_pixel_6x8);
    theme::rect(parent, 6, 98, 308, 40, theme::surface());
    theme::rect(parent, 6, 98, 3, 40, theme::pink());
    struct ProfileMetric {
        const char *label;
        const char *value;
    };
    char bw[12]{};
    char sf[8]{};
    char cr[8]{};
    char sync[8]{};
    std::snprintf(bw, sizeof(bw), "%uk",
                  static_cast<unsigned>(profile.bandwidth_hz / 1000U));
    std::snprintf(sf, sizeof(sf), "%u", profile.spreading_factor);
    std::snprintf(cr, sizeof(cr), "4/%u", profile.coding_rate_denominator);
    std::snprintf(sync, sizeof(sync), "%04X", profile.sync_word);
    const std::array<ProfileMetric, 4> metrics = {{
        {"BW", bw}, {"SF", sf}, {"CR", cr}, {"SYNC", sync},
    }};
    for (std::size_t index = 0; index < metrics.size(); ++index) {
        const lv_coord_t x = 18 + static_cast<lv_coord_t>(index) * 76;
        put_label(parent, metrics[index].label, x, 104, theme::pink(), &font_pixel_6x8);
        put_label(parent, metrics[index].value, x, 118, theme::text(), &font_mono_10);
    }
    std::snprintf(line, sizeof(line), "PRESET %lu OF %lu   UP / DOWN",
                  static_cast<unsigned long>(onboarding_profile_selection + 1U),
                  static_cast<unsigned long>(count));
    put_centered_label(parent, line, 148, theme::text_muted(), &font_pixel_6x8);
    const bool profile_failed = std::strstr(shell_notice, "FAILED") != nullptr;
    if(profile_failed) {
        put_centered_label(parent, shell_notice, 168, theme::fault(), &font_pixel_6x8);
        put_centered_label(parent, "CHOOSE AGAIN OR ENTER TO RETRY", 182,
                           theme::text_muted(), &font_pixel_6x8);
    } else {
        put_centered_label(parent, "MATCH THE NEARBY NETWORK", 168,
                           theme::text_muted(), &font_pixel_6x8);
        put_centered_label(parent, "AND THE RADIO RULES WHERE YOU OPERATE", 182,
                           theme::text_muted(), &font_pixel_6x8);
    }
    add_action_strip(parent, "BACK", profile_failed ? "ENTER  RETRY" : "ENTER  APPLY",
                     profile_failed ? theme::fault() : theme::cyan());
}

