void build_spectrum_confirmation(lv_obj_t * parent)
{
    add_setup_header(parent, "SPECTRUM", "FIRST USE");
    put_centered_label(parent, "PACKET CAPTURE PAUSES", 30,
                       theme::amber(), &font_pixel_6x8);
    put_centered_label(parent, "DURING A SCAN", 42,
                       theme::amber(), &font_pixel_6x8);
    put_centered_label(parent, "THE SX1262 CHANGES RADIO MODE WHILE SWEEPING.", 58,
                       theme::text(), &font_pixel_6x8);
    put_centered_label(parent, "LILYSHARK RESTORES YOUR ACTIVE PROFILE AND RX", 72,
                       theme::text_muted(), &font_pixel_6x8);
    put_centered_label(parent, "BEFORE REPORTING COMPLETION, CANCEL, OR FAILURE.", 86,
                       theme::text_muted(), &font_pixel_6x8);
    constexpr std::array<std::array<const char *, 2>, 3> choices = {{
        {{"CANCEL", "KEEP RECEIVING"}},
        {{"FAST NARROW", "11 BINS / ACTIVE CHANNEL"}},
        {{"DEEP BAND", "REGIONAL / HIGH DETAIL"}},
    }};
    for(std::size_t index = 0; index < choices.size(); ++index) {
        add_pixel_list_row(parent, 119 + static_cast<lv_coord_t>(index) * 27, 27,
                           choices[index][0], choices[index][1],
                           spectrum_confirmation_selection == index,
                           index == 0U ? theme::text_muted() : theme::amber());
    }
    add_action_strip(parent, "BACK  CANCEL", "ENTER  CONFIRM",
                     spectrum_confirmation_selection == 0U ? theme::cyan() : theme::amber());
}

void build_reset_confirmation(lv_obj_t * parent)
{
    add_setup_header(parent, "RESET", "SETUP");
    put_centered_label(parent, "RUN FIRST-TIME SETUP AGAIN?", 36,
                       theme::amber(), &font_pixel_6x8);
    put_centered_label(parent, "SAVED RADIO PROFILE AND CAPTURE FILES REMAIN.", 56,
                       theme::text(), &font_pixel_6x8);
    put_centered_label(parent,
                       reset_save_failed ? "SETTINGS SAVE FAILED - NOTHING WAS RESET"
                                         : "DISPLAY AND INPUT PREFERENCES RESET.",
                       74, reset_save_failed ? theme::fault() : theme::text_muted(),
                       &font_pixel_6x8);
    constexpr std::array<const char *, 2> choices = {{"NO  KEEP SETTINGS", "YES  RUN SETUP"}};
    for(std::size_t index = 0; index < choices.size(); ++index) {
        add_pixel_list_row(parent, 100 + static_cast<lv_coord_t>(index) * 32, 32,
                           choices[index], "", reset_confirmation_yes == (index == 1),
                           index == 1 ? theme::fault() : theme::text());
    }
    add_action_strip(parent, "BACK  CANCEL",
                     reset_save_failed ? "ENTER  RETRY" : "ENTER  CONFIRM",
                     reset_confirmation_yes ? theme::fault() : theme::cyan());
}

void build_shell_screen(lv_obj_t * parent)
{
    switch(app_shell.route()) {
        case ShellRoute::Splash: build_splash(parent); break;
        case ShellRoute::OnboardingWelcome: build_onboarding_welcome(parent); break;
        case ShellRoute::OnboardingCapabilities: build_onboarding_capabilities(parent); break;
        case ShellRoute::OnboardingNetwork: build_onboarding_network(parent); break;
        case ShellRoute::OnboardingProfile: build_onboarding_profile(parent); break;
        case ShellRoute::OnboardingControls: build_onboarding_controls(parent); break;
        case ShellRoute::OnboardingReadiness: build_onboarding_readiness(parent); break;
        case ShellRoute::Home: build_home(parent); break;
        case ShellRoute::RadioProfiles: build_radio_profiles(parent); break;
        case ShellRoute::Settings: build_settings(parent); break;
        case ShellRoute::Storage: build_storage(parent); break;
        case ShellRoute::DeviceStatus: build_device_status(parent); break;
        case ShellRoute::DisplayInput: build_display_input(parent); break;
        case ShellRoute::Help: build_help(parent); break;
        case ShellRoute::About: build_about(parent); break;
        case ShellRoute::SpectrumConfirmation: build_spectrum_confirmation(parent); break;
        case ShellRoute::ResetConfirmation: build_reset_confirmation(parent); break;
        case ShellRoute::Analyzer:
        case ShellRoute::Count: break;
    }
}

void build_current_screen();

void build_chat(lv_obj_t * parent)
{
    const std::uint32_t dest = chat_active_dest();
    chat_clear_peer_unread(dest);
    const bool broadcast = dest == 0xffffffffU;
#if defined(LILYSHARK_DEVICE)
    add_status_bar(parent, "CHAT");
#else
    add_simulator_live_status_bar(parent, "CHAT");
#endif
    const std::size_t tab0 = chat_tab_first();
    const std::size_t shown = chat_tab_shown();
    const lv_coord_t tab_w = static_cast<lv_coord_t>(320 / shown);
    for (std::size_t index = 0; index < shown; ++index) {
        const std::size_t peer = tab0 + index;
        const lv_coord_t x = static_cast<lv_coord_t>(index) * tab_w;
        const bool selected = peer == chat_peer_index;
        const bool all = chat_peers[peer].node == 0xffffffffU;
        const std::uint8_t unread = chat_peers[peer].unread;
        if (selected) {
            draw_outline_rect(parent, x + 2, kChatTabY, tab_w - 4, kChatTabH, theme::pink());
        }
        const lv_coord_t name_w = (all && unread == 0U) ? tab_w - 12 : tab_w - 28;
        put_clipped_label(parent, chat_peers[peer].name, x + 6, kChatTabY + 4,
                          name_w > 24 ? name_w : 24,
                          selected ? theme::pink() : theme::text_muted(), &font_pixel_6x8);
        if (unread > 0U && !selected) {
            const lv_coord_t badge_x = x + tab_w - 16;
            theme::rect(parent, badge_x, kChatTabY + 3, 12, 10, theme::pink());
            char badge[4]{};
            if (unread < 10U) {
                std::snprintf(badge, sizeof(badge), "%u", static_cast<unsigned>(unread));
            } else {
                std::snprintf(badge, sizeof(badge), "+");
            }
            put_label(parent, badge, badge_x + 3, kChatTabY + 4, theme::on_accent(),
                      &font_pixel_6x8);
        } else if (!all) {
            put_label(parent, "DM", x + tab_w - 20, kChatTabY + 4,
                      selected ? theme::pink() : theme::text_muted(), &font_pixel_6x8);
        }
    }
    theme::rule_line(parent, 0, kChatRuleY, 320, 1, theme::pink());

    std::size_t match_slots[kChatLogCapacity]{};
    std::size_t match_count = 0;
    for (std::size_t index = 0; index < chat_log_count; ++index) {
        const std::size_t slot = (chat_log_start + index) % kChatLogCapacity;
        if (chat_log[slot].peer != dest) continue;
        match_slots[match_count++] = slot;
    }
    const std::size_t visible = match_count < kChatVisible ? match_count : kChatVisible;
    const std::size_t max_off = match_count > visible ? match_count - visible : 0U;
    if (chat_scroll_offset > max_off) chat_scroll_offset = max_off;
    const std::size_t first = match_count == 0U ? 0U :
        match_count - visible - chat_scroll_offset;
    theme::rect(parent, 0, kChatOlderY + 1, 320, kChatOlderH - 1, lv_color_hex(0x050808));
    if (match_count > visible) {
        char older[20]{};
        std::snprintf(older, sizeof(older), "%u OLDER",
                      static_cast<unsigned>(first));
        put_label(parent, first > 0U ? older : "NEWEST", 8, kChatOlderY + 4,
                  theme::text_muted(), &font_pixel_6x8);
        // "UP"/"DOWN" described the key, not the result. These say where they
        // take you, and the boxes are the actual tap targets.
        draw_outline_rect(parent, kChatOlderBtnX, kChatOlderY + 1, kChatOlderBtnW,
                          kChatOlderH - 2, theme::pink());
        put_label(parent, "OLDER", kChatOlderBtnX + 7, kChatOlderY + 4, theme::pink(),
                  &font_pixel_6x8);
        draw_outline_rect(parent, kChatNewerBtnX, kChatOlderY + 1, kChatNewerBtnW,
                          kChatOlderH - 2, theme::pink());
        put_label(parent, "NEWER", kChatNewerBtnX + 7, kChatOlderY + 4, theme::pink(),
                  &font_pixel_6x8);
    }
    if (chat_peer_count > shown) {
        char extra[8]{};
        std::snprintf(extra, sizeof(extra), "+%u",
                      static_cast<unsigned>(chat_peer_count - shown));
        put_label(parent, extra, 148, kChatOlderY + 4, theme::pink(), &font_pixel_6x8);
    }
    put_label(parent, broadcast ? "TO ALL" : "PRIVATE", 258, kChatOlderY + 4,
              theme::pink(), &font_pixel_6x8);
    theme::rule_line(parent, 0, kChatOlderY + kChatOlderH, 320, 1, theme::pink());

    if (visible == 0U) {
        draw_outline_rect(parent, 16, 78, 288, 86, theme::pink());
        put_label(parent, "NO MESSAGES YET", 28, 94, theme::pink(),
                  &font_pixel_6x8);
        put_label(parent, broadcast ? "EVERYONE ON THIS CHANNEL WILL SEE THIS." :
                                      "ONLY THIS NODE WILL SEE THIS.",
                  28, 116, theme::text_muted(), &font_pixel_6x8);
        put_label(parent, "TYPE, THEN PRESS ENTER TO SEND.", 28, 132,
                  theme::text_muted(), &font_pixel_6x8);
    } else {
        for (std::size_t index = 0; index < visible; ++index) {
            const ChatLine &line = chat_log[match_slots[first + index]];
            const lv_coord_t y = kChatMsgY + static_cast<lv_coord_t>(index) * kChatRowH;
            // Your own lines are indented and edged in pink, theirs are flush
            // left and edged in cyan. The only mark before was an 8 px bar at
            // the far right, which reads as a scrollbar, so a conversation
            // looked like one voice talking to itself.
            const lv_coord_t text_x = line.mine ? 58 : 14;
            const lv_coord_t text_w = line.mine ? 248 : 292;
            theme::rect(parent, line.mine ? 310 : 4, y, 6, 24,
                        line.mine ? theme::pink() : theme::cyan());
            char who[28]{};
            // The destination is already stated once above the log; repeating
            // ALL or PRIVATE on every line was noise, and the operator's own
            // call sign told them nothing they did not know.
            if (line.when[0] != '\0') {
                std::snprintf(who, sizeof(who), "%s  %s", line.when,
                              line.mine ? "YOU" : line.from);
            } else {
                std::snprintf(who, sizeof(who), "%s", line.mine ? "YOU" : line.from);
            }
            put_label(parent, who, text_x, y,
                      line.mine ? theme::pink() : theme::cyan(), &font_pixel_6x8);
            put_clipped_label(parent, line.text, text_x, y + 11, text_w, theme::text(),
                              &font_mono_semibold_12);
        }
    }
    if (chat_tx_failed || std::strstr(shell_notice, "TX FAILED") != nullptr) {
        theme::rect(parent, 4, 184, 312, 12, lv_color_hex(0x180808));
        put_label(parent, "TX FAILED", 10, 185, theme::fault(), &font_pixel_6x8);
    }
    draw_outline_rect(parent, 4, 196, 248, 26, theme::pink());
    put_label(parent, ">", 10, 203, theme::pink(), &font_pixel_6x8);
    put_clipped_label(parent,
                      chat_draft[0] == '\0' ? "TYPE A MESSAGE" : chat_draft,
                      22, 203, 200,
                      chat_draft[0] == '\0' ? theme::text_muted() : theme::text(),
                      chat_draft[0] == '\0' ? &font_pixel_6x8 : &font_mono_semibold_12);
    if (chat_draft_len > 0U) {
        const unsigned left = static_cast<unsigned>(
            (sizeof(chat_draft) > 1U ? sizeof(chat_draft) - 1U : 0U) - chat_draft_len);
        char remain[4]{};
        std::snprintf(remain, sizeof(remain), "%u", left);
        const lv_coord_t remain_w = static_cast<lv_coord_t>(std::strlen(remain) * 6);
        put_label(parent, remain, 244 - remain_w, 204,
                  left < 10U ? theme::pink() : theme::text_muted(), &font_pixel_6x8);
    }
    draw_outline_rect(parent, kChatSendX, kChatSendY, kChatSendW, kChatSendH, theme::pink());
    put_label(parent, "SEND", kChatSendX + 10, kChatSendY + 6, theme::pink(),
              &font_pixel_6x8);
}

void send_chat_draft() noexcept
{
    if (chat_draft_len == 0) return;
    const std::uint32_t dest = chat_active_dest();
#if defined(LILYSHARK_DEVICE)
    const bool ok = ::transmit_meshtastic(MeshtasticPort::TextMessage, chat_draft, dest);
    if (!ok) {
        chat_tx_failed = true;
        std::snprintf(shell_notice, sizeof(shell_notice), "TX FAILED");
        return;
    }
#else
    chat_push("ME", chat_draft, true, dest);
#endif
    chat_tx_failed = false;
    if (std::strstr(shell_notice, "TX FAILED") != nullptr) shell_notice[0] = '\0';
    chat_draft[0] = '\0';
    chat_draft_len = 0;
    chat_scroll_offset = 0;
}

bool handle_chat_key(std::uint32_t key) noexcept
{
    if (key == LV_KEY_ESC ||
        ((key == LV_KEY_BACKSPACE || key == 8U) && chat_draft_len == 0)) {
        open_field_tab(FieldTab::Lily);
        return true;
    }
    if (key == '\t') {
        chat_cycle_dest(1);
        build_current_screen();
        return true;
    }
    if (key == LV_KEY_UP) {
        ++chat_scroll_offset;
        build_current_screen();
        return true;
    }
    if (key == LV_KEY_DOWN) {
        if (chat_scroll_offset > 0U) --chat_scroll_offset;
        build_current_screen();
        return true;
    }
    if (key == LV_KEY_LEFT || key == LV_KEY_PREV) {
        open_field_tab(FieldTab::Map);
        return true;
    }
    if (key == LV_KEY_RIGHT || key == LV_KEY_NEXT) {
        open_field_tab(FieldTab::Radio);
        return true;
    }
    if (key == LV_KEY_BACKSPACE || key == 8U) {
        if (chat_draft_len > 0) {
            chat_draft[--chat_draft_len] = '\0';
            chat_tx_failed = false;
            build_current_screen();
        }
        return true;
    }
    if (key == LV_KEY_ENTER || key == '\r') {
        send_chat_draft();
        build_current_screen();
        return true;
    }
    if (key >= 32 && key < 127 && chat_draft_len + 1U < sizeof(chat_draft)) {
        chat_draft[chat_draft_len++] = static_cast<char>(key);
        chat_draft[chat_draft_len] = '\0';
        chat_tx_failed = false;
        build_current_screen();
        return true;
    }
    return key < 256;
}

void build_current_screen()
{
    root = lv_screen_active();
    lv_obj_clean(root);
    theme::style_screen(root);
    lv_obj_add_flag(root, LV_OBJ_FLAG_CLICKABLE);
    trace_buffer_index = 0;

    if (chat_open) {
        build_chat(root);
    } else if(app_shell.route() != ShellRoute::Analyzer) {
        build_shell_screen(root);
    } else {
        switch(current_screen) {
            case Screen::traffic: build_traffic(root); break;
            case Screen::traffic_filter: build_traffic_filter(root); break;
            case Screen::protocols: build_protocols(root); break;
            case Screen::protocol_detail: build_protocol_detail(root); break;
            case Screen::spectrum: build_spectrum(root); break;
            case Screen::nodes: build_nodes(root); break;
            case Screen::node_detail: build_node_detail(root); break;
            case Screen::packet_detail: build_packet_detail(root); break;
            case Screen::map: build_map(root); break;
            case Screen::survey: build_survey(root); break;
            case Screen::utilization: build_utilization(root); break;
            case Screen::timeline: build_timeline(root); break;
            case Screen::events: build_events(root); break;
            case Screen::count: break;
        }
    }
    if (field_chrome_active()) {
        FieldTab nav = FieldTab::Count;
        const ShellRoute route = app_shell.route();
        if (chat_open) nav = FieldTab::Chat;
        else if (route == ShellRoute::Home) nav = FieldTab::Lily;
        else if (route == ShellRoute::Analyzer) nav = field_tab;
        add_field_nav(root, nav);
    }
}

